quests[70662] = { id = 70662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenarbeit" }
quests[70697] = { id = 70697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Expertenmeinung", description = "Lubbins Wunden sind verheilt, aber ich fürchte, sein Selbstvertrauen hat stark gelitten. Ich glaube, es ist an der Zeit, andere um Hilfe zu bitten.\n\nWeit im Südwesten in einer entlegenen Region des Azurblauen Gebirges gibt es eine Kampfhaustiertrainerin namens Flicki. Sie gehört zu den weltbesten Experten in dieser Sache.\n\nStattet ihr bitte einen Besuch ab. Ich bin sicher sie kann Lubbins helfen!", sourceObjective = "Sprecht mit Flicki im Azurblauen Gebirge.", completion = "Jyhanna hat Euch zur richtigen Tuskarr geschickt, {name}. Wir werden Lubbins' altes Ich im Nu wiedererwecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[70698] = { id = 70698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forscherin Schleichflügel" }
quests[70699] = { id = 70699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katalogisieren von Thaldraszus" }
quests[70701] = { id = 70701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bakar träumen von verirrten Riesenwildschafen", description = "Einige Riesenwildschafe des Klans sind mal wieder von der Herde weggewandert.\n\nDer Grat um uns ist für unsere Schäfer zu gefährlich, um nach ihnen zu suchen. Es wäre ein großer Segen für uns, wenn Ihr einen unserer Bakars nehmen und die Riesenwildschafe zurückbringen könntet. Unsere Schäfer können Euch die richtige Richtung weisen.", sourceObjective = "Bringt die verirrten Riesenwildschafe zurück zum Klan Aylaag.", completion = "Wir müssen wachsam sein, was unser Vieh angeht. Unsere Ressourcen sind an sich schon begrenzt. Ein Riesenwildschaf zu verlieren ist ein Rückschlag, den wir gern vermeiden wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70702] = { id = 70702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgesetzte Portalerkundung", description = "<Der laute, kreischende Ruf des kleinen Boten erregt Eure Aufmerksamkeit. Er drückt Euch eine Notiz in die Hand und rennt davon.\n\nAuf dem Zettel ist eine Nachricht von Thaelin Schwarzamboss, der Eure Hilfe benötigt.>", sourceObjective = "Trefft Thaelin Schwarzamboss im Außenposten der Rubinschuppen an der Küste des Erwachens.\n\nBereitgestellter Gegenstand:", completion = "Ich sehe, Ihr habt meinen Brief gefunden. Schön, Euch wiederzusehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[70703] = { id = 70703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Vermächtnis von Tyrhold", description = "Hüter Tyr liebte seine Rätsel. In dem Geschenk, das er uns gegeben hat, liegt sicherlich eine tiefere Bedeutung. Da er diese Schuppe höchstwahrscheinlich in der ehemaligen Zitadelle geschmiedet hat, ist sie vielleicht der Schlüssel, der uns dabei hilft, ihre Geheimnisse zu enthüllen.\n\nGeht mit Koranos nach Tyrhold, {name}. Ich bin mir sicher, dass er als vertrauenswürdiger Berater und Hüter dieses Lands Einsicht in diese Angelegenheit erhalten wird.", sourceObjective = "Untersucht mit Koranos die Silberschuppe in Tyrhold.", progress = "Habt Ihr etwas herausgefunden?", completion = "Diese Magie... Ihr habt etwas in Tyrhold erweckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[70706] = { id = 70706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal: Schattenzuflucht", description = "Unsere Expedition berichtet von einem inaktiven Stein bei den üppigen Hängen im Südwesten. Es ist ein gutes Stück entfernt, aber es lohnt sich, jemanden mit Eurer Kenntnis für die Untersuchung dort hinzuschicken.", sourceObjective = "Findet das inaktive Portal bei der Schattenzuflucht auf den Ebenen von Ohn'ahra.", sourceObjectiveStatus = "unverified-source-field" }
quests[70707] = { id = 70707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Next Waygate" }
quests[70708] = { id = 70708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grotte", description = "Fühlt sich an, als wären es Jahre gewesen. Aber auch irgendwie nur nach Minuten.\n\nIch könnte jemanden zum Reden brauchen, wenn Ihr Zeit hättet.\n\nWollt Ihr uns etwas zu trinken holen? Holt einfach, was Ihr wollt. Geht auf mich.", sourceObjective = "Trinkt etwas mit Kolgar.", progress = "Ich weiß, dass ich Euch mehr als nur ein Getränk schulde, aber ich hoffe, das hier ist vorerst genug.", completion = "Ich schätze, es wird Zeit zu gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70710] = { id = 70710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stromschnellenstrecke", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[70711] = { id = 70711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stromschnellenstrecke - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[70712] = { id = 70712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenreiterrennen - Stromschnellenstrecke" }
