quests[70719] = { id = 70719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenschlitzer Trakken" }
quests[70720] = { id = 70720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gibt's nicht" }
quests[70721] = { id = 70721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So schön, ich fall in Ohn'macht...", description = "Es gibt einen kleinen Teich beim Spiegel des Himmels, wo Narman und ich uns während meiner Initiandenausbildung zum ersten Mal begegnet sind.\n\nInitianden reisen an diesen Ort, um Ohn'ahra näher zu sein und so den Wind zu spüren. Zuerst sah ich ihn in der Spiegelung des Wassers, als meine Augen plötzlich durch eine Brise geöffnet wurden. Es gibt auf den Ebenen keinen schöneren Anblick.\n\nDer Teich bildet den perfekten Ort für unseren Antrag.", sourceObjective = "Helft dem Windweisen Dawa und Jäger Narman bei ihren Anträgen.", completion = "Vielen Dank, {name}.\n\nDawa und ich werden nie vergessen, was Ihr für uns getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[70722] = { id = 70722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was Lubbins braucht", description = "Ich glaube, ich weiß jetzt, was wir tun müssen, {name}.\n\nAber lasst uns zuerst darüber reden!\n\nIch habe sogar ein Geschenk für Euch, wenn wir fertig sind. Toll, oder?", sourceObjective = "Sprecht mit Flicki in Iskaara.", completion = "Beschwört Lubbins und wendet dann diesen Kampfstein auf ihn an. Es wird ihn dauerhaft stärker machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70723] = { id = 70723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erdprimalisten zerschmettern", description = "Rethelshi in Valdrakken wird dankbar sein, dies zur Erforschung der Primalisten in die Hände zu bekommen.", sourceObjective = "Bringt den Urkern zu Rethelshi.\n\nBereitgestellter Gegenstand:", completion = "Das wird unseren Forschungen zu den Primalisten helfen. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[70730] = { id = 70730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geber der Shikaar", sourceObjective = "Helft dem Windweisen Dawa bei der Vorbereitung des perfekten Antrags.", progress = "Narman hat eine Geste verdient, die so groß ist wie er.", completion = "Arbhogs Hörner? Die eignen sich bestens.\n\nArbhog war einst der Stärkste unter den Moschushirschen der Ebenen. Ein passendes Geschenk für den stärksten Jäger. Ich bin mir sicher, dass Narman das wertschätzen wird.\n\nVielleicht bringt er mir ja eines Tages das Jagen bei. Ein Jägersmann der Ohn'ir. Ha! Stell sich das mal einer vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[70732] = { id = 70732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übungskampf", description = "Also gut! Nachdem Ihr den Stein auf Lubbins angewendet habt, sollten wir eine Proberunde veranstalten, um seine Fertigkeiten zu testen!\n\nEs gibt einen großen, alten Flunker namens Gwosh, der an der Küste nördlich von hier lebt. Gwosh liebt das Kämpfen! Naja, eher das Spielen. Er kommt auch super mit anderen Haustieren aus!\n\nDas wird der perfekte Spaß... ich meine Kampf... für Lubbins.", sourceObjective = "Besiegt Gwosh im Haustierkampf.", progress = "Gwosh ist sehr sanft, aber auch ungestüm. Ich glaube, er und Lubbins werden viel Spaß haben.\n\nGeht von hier nach Norden, dann findet Ihr ihn.", completion = "Das lief ganz hervorragend! Gut gemacht, Lubbins!\n\nMacht Euch keine Sorgen um Gwosh, er ist ein altes Weichei. Er wird sich erholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70738] = { id = 70738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Yougaklasse", description = "Alles lief sehr gut, aber jetzt? Elementare sorgen für einige... ähm... kleine Herausforderungen.\n\nUnsere Gäste genossen die Einrichtungen, als plötzlich all diese Elementare erschienen! Diese widerwärtigen Bestien haben alles gestört. Vermutlich sogar die neue Yougalehrerin.\n\nOh ja, Youga sind neuartige Dehnungsübungen, bei denen Ihr gleichzeitig meditiert. Ich bin mir sicher, dass Lehrerin und Schüler beide so entspannt sind, dass sie die Elementare nicht einmal bemerken.\n\nDennoch, es ist besser auf Nummer sicher zu gehen. Bitte, seht nach ihnen.", sourceObjective = "Findet die Lehrerin und 6 Yougaschüler.", completion = "Hoffentlich verpassen sie uns deswegen keine schlechten Bewertungen!", sourceObjectiveStatus = "unverified-source-field" }
quests[70739] = { id = 70739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutlinien, Süßigkeiten und Teerai", description = "Ich habe mit Khanen gejagt, die schnellsten Bakar eingeholt und einen voll ausgewachsenen Brüffelchbullen mit bloßen Händen niedergerungen. Als Jäger habe ich nichts weiter zu beweisen.\n\nAls Partner hingegen habe ich noch viel zu lernen.\n\nWindweiser Dawa von Klan Ohn'ir ist mein Herz und Glück. Ich möchte mich nur als seiner Liebe würdig erweisen, doch ich weiß nichts von Traditionen und Ritualen. Ich benötige die Weisheit der Ältesten in Maruukai.", sourceObjective = "Helft Jäger Narman, einen traditionellen Segen für seinen Heiratsantrag zu erhalten.", progress = "Was, wenn ich nicht gut genug für Dawas Liebe bin?", completion = "Eher würde ich alle Sterne am Nachthimmel darum bitten, mich zu bewundern, als zu behaupten, dass ich Dawas Liebe voll und ganz würdig bin.\n\nNichtsdestotrotz werde ich den Mut finden, voranzuschreiten. Werdet Ihr mir bei einem grandiosen Antrag helfen, wenn die Zeit gekommen ist?", sourceObjectiveStatus = "unverified-source-field" }
quests[70740] = { id = 70740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dampfreinigung", description = "Xijan scheint zu glauben, dass die Elementarinvasion auf unser schönes Bad nur ein kleines Problem ist, aber diese Flut aus Flammen und Dampf muss sofort unter Kontrolle gebracht werden.\n\nWir hatten Musikgruppen engagiert, die im unteren Bad spielen sollten, aber die Elementare haben ihre Ausrüstung zerstört. Da wir in dieser Gegend noch nie ein solches Ausmaß an elementarer Zerstörung hatten, vermute ich, dass Primalisten dahinterstecken.\n\nFalls Ihr Euch nützlich machen wollt, beseitigt die Elementare auf der Ostseite des unteren Bads. Dort planen wir die ersten Auftritte.", sourceObjective = "Tötet 12 Elementare im unteren Bad.", completion = "Ein guter Anfang, aber für meinen Geschmack sind immer noch zu viele übrig...", sourceObjectiveStatus = "unverified-source-field" }
quests[70741] = { id = 70741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar liebste Dinge", description = "<So wie es aussieht, ist die Yougaklasse unterbrochen worden, und die Habseligkeiten der Studenten liegen überall verteilt.\n\nDiese Gegenstände einzusammeln, wird dem Bad der Ruhigen Träume sicher helfen.>", sourceObjective = "Sammelt 6 verlorene Habseligkeiten.", completion = "Es ist sehr nett von Euch, dass Ihr diese Gegenstände gesammelt habt. Wir werden sie sofort ihren rechtmäßigen Besitzern zurückgeben!", sourceObjectiveStatus = "unverified-source-field" }
quests[70742] = { id = 70742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liegt in der Familie", description = "Aus der Luft habe ich eines der Artefakte, die Edress am Eingang der Ruinen gefunden hatte, gesehen. Drinnen gibt es zweifelsohne noch mehr.\n\nSie sind irgendwie durch Magie geschützt, aber ich muss näher herangehen, bevor ich sie untersuchen kann. Die Magie hier ist sehr alt.\n\nDas Gelände scheint verlassen zu sein. Aber ich würde nicht darauf vertrauen, dass das lange so bleibt, wenn wir erst einmal tätig werden. Haltet die Augen offen. Wir werden alles aufdecken, was wir können.", sourceObjective = "Durchsucht das Obsidianobservatorium nach Hinweisen auf die Vergangenheit der Dracthyr.", completion = "Es gibt vieles, worüber ich nachdenken muss... Ich würde jetzt gern etwas Zeit allein verbringen, wenn es nichts ausmacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[70743] = { id = 70743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armes Baby", sourceObjective = "Findet ElzarasBaby.", completion = "<Elzara ignoriert Euch und schaut Baby an.>\n\nBist du in Sicherheit, mein herzallerliebster Schnuffelpuff?\n\nHaben die Primalisten dich angeblutet? Wie können sie es wagen!\n\n<Elzara bemerkt Euch.>\n\nIch werde diesem Bad nicht mehr als einen Stern geben. Ich erwarte ein blutfreies Erlebnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[70744] = { id = 70744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaut Euch die Knochen an!", description = "<Der Badmanager würde es bestimmt zu schätzen wissen, wenn hier nicht überall Blut wäre...>", sourceObjective = "Macht 10 Sauereien sauber.", completion = "Ich will es nicht wissen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[70745] = { id = 70745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzwungene Entspannung", description = "Diese Primalisten, die Ihr gesehen habt, sehen meiner Ansicht nach nicht nach Anführern aus. Wer würde sich schon vor einem kleinen Hund fürchten?\n\nAlso, falls sie Vadne erwähnt haben, hört sich das nach ihrer Anführerin an. Sie muss diejenige sein, die diese Elementare hereinbringt. Wir müssen die Beschwörerin ausschalten. Um solch einen Ärger verursachen zu können, muss sie sich ganz in der Nähe aufhalten. Überprüft die Höhle direkt unter uns. Ich weiß, dass die weniger gewissenhaften Angestellten dort gerne eine längere Pause einlegen.", sourceObjective = "Tötet die Elementarbeschwörerin.", completion = "Ich bin froh, dass es endlich besser wird! Wir alle haben uns eine Pause verdient.\n\nIch hoffe, dass Ihr hier auch einen kurzen Augenblick der Ruhe findet: Das habt Ihr Euch verdient, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70746] = { id = 70746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blau ist nicht gleich blau", sourceObjective = "Begleitet Glutthal und Telash zum Lager Antonidas.", progress = "Bewahrt einen klaren Kopf und haltet Eure Flügel bereit, mein Freund.", completion = "Noch ist kein blauer Drache in Sicht, nur jede Menge ihrer Untergebenen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70747] = { id = 70747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der azurblaue Zauberer", sourceObjective = "Sprecht mit Erzmagier Khadgar im Lager Antonidas.", completion = "Im Namen der Kirin Tor möchte ich meine große Sorge darüber zum Ausdruck bringen, was Malygos Eurem Volk angetan hat.\n\nDer Vorgang verlangt eine sofortige Untersuchung.\n\n...Wo sind Eure Begleiter?", sourceObjectiveStatus = "unverified-source-field" }
quests[70748] = { id = 70748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur für blaue Augen", description = "Kein Wunder, dass Eure Gefährten noch nichts gefunden haben.\n\nDiese Bücher waren nur für Augen der Blauen gedacht.\n\nDoch meine Gegenwart sollte ausreichen, damit wir die Geheimnisse einiger wichtiger Bände entdecken können.", sourceObjective = "Durchsucht die Azurarchive nach Malygos' Notizen.", completion = "Ihr habt Eure Antworten gefunden und doch seht Ihr bekümmert aus...\n\nEs tut mir leid.", sourceObjectiveStatus = "unverified-source-field" }
quests[70750] = { id = 70750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützt das Abkommen", description = "Ihr da! Ja, ich spreche mit Euch. Oder seht Ihr noch jemand anderen hier?\n\n<Therazal wirft einen kurzen Blick auf einige Passanten.>\n\nIgnoriert sie. Sie sind nicht Teil dieses Auftrags. Von Euch habe ich gehört und mit Euch wünsche ich zu sprechen!\n\nDas Valdrakkenabkommen hat mich damit beauftragt, diejenigen ausfindig zu machen, die sich auf den Inseln einen Namen gemacht haben und die danach streben, dass unsere Verbündeten und deren Sicherheit weiterhin oberste Priorität bleiben.\n\nTut, was Ihr am besten könnt, <Kamerad/Kameradin>. Ihr sollt großzügig belohnt werden.", sourceObjective = "Führt Eure Bemühungen fort, dem Valdrakkenabkommen und seinen Verbündeten auf den ganzen Dracheninseln zu helfen.", completion = "Ja, ich bin in der Tat beeindruckt, Kamerad. Als Repräsentant des Abkommens kann ich Euch versichern, dass Eure Bemühungen nicht unbemerkt geblieben sind!\n\nBitte nehmt dies, im Auftrag unserer Verbündeten.", sourceObjectiveStatus = "unverified-source-field" }
quests[70751] = { id = 70751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terillod der Andächtige" }
quests[70752] = { id = 70752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wasserprimalisten verdampfen", description = "Rethelshi in Valdrakken wird dankbar sein, dies zur Erforschung der Primalisten in die Hände zu bekommen.", sourceObjective = "Bringt den Urkern zu Rethelshi.\n\nBereitgestellter Gegenstand:", completion = "Das wird unseren Forschungen zu den Primalisten helfen. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[70753] = { id = 70753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Luftprimalisten verwehen", description = "Rethelshi in Valdrakken wird dankbar sein, dies zur Erforschung der Primalisten in die Hände zu bekommen.", sourceObjective = "Bringt den Urkern zu Rethelshi.\n\nBereitgestellter Gegenstand:", completion = "Das wird unseren Forschungen zu den Primalisten helfen. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[70754] = { id = 70754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Feuerprimalisten löschen", description = "Rethelshi in Valdrakken wird dankbar sein, dies zur Erforschung der Primalisten in die Hände zu bekommen.", sourceObjective = "Bringt den Urkern zu Rethelshi.\n\nBereitgestellter Gegenstand:", completion = "Das wird unseren Forschungen zu den Primalisten helfen. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[70763] = { id = 70763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenschnitzer A'tir" }
quests[70766] = { id = 70766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zerrüttete Flamme", description = "Der Gorloc umklammert ein Tagebuch, dessen Umschlag durch Feuchtigkeit und Unachtsamkeit beschädigt wurde. Das verblasste Symbol der Splitterflammen scheint stolz durch die Risse und Verfärbungen hindurch.\n\nVielleicht werdet Ihr, wenn Ihr die fehlenden Seiten findet, ein besseres Verständnis von Eroberin Makko und dem Wahnsinn bekommen, der ihre Psyche zerrüttet hat.", sourceObjective = "Sammelt die Seiten von Makkos Tagebuch von Gorlocs in Szar Skeleth ein.", progress = "Ein Tagebuch? Von wem geschrieben?", completion = "Danke, aber das könnt Ihr behalten.\n\n<Toddy rollt mit den Augen.>\n\nUnd davor habe ich gedacht, die Splitterflammen seien verrückt...", sourceObjectiveStatus = "unverified-source-field" }
quests[70779] = { id = 70779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarjins Geschichten", description = "<Tarjin blickt weiterhin auf die Insel in der Ferne, während er mit Euch spricht.>\n\nHaltet Ihr Euch der unglaublichen Legenden und Geschichten der Djaradin für würdig?\n\nIhr seid ja kaum so groß wie eine unserer Waffen. Pfft.\n\nIch bezweifle, dass Ihr den Mut habt, das Erbe meines Volkes anzutreten.\n\nÜberzeugt mich vom Gegenteil, wenn Ihr könnt. Sucht nach den Drachen, den einzigen würdigen Rivalen auf diesen Inseln.\n\nBringt mir Trophäen Eures Sieges über die Stärksten von ihnen.", sourceObjective = "Sammelt 5 beeindruckende Drachenschädel von mächtigen Drachen und Protodrachen der Dracheninseln.", progress = "Wenn Ihr nicht gegen Eure kostbaren Drachenschwärme kämpfen wollt, könnt Ihr Euch den Protodrachen stellen. Sie bieten immer noch einen guten Kampf.", completion = "<Tarjin wirft die Schädel über seine Schulter in die Lavagrube hinter ihm.>\n\nBeeindruckend, für einen Schwächling.", sourceObjectiveStatus = "unverified-source-field" }
quests[70780] = { id = 70780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banner von Ohn'ahra" }
quests[70781] = { id = 70781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus heiterem Himmel", description = "Habt Ihr das gesehen?!\n\nDiese geflügelte Kreatur fiel gerade vom Himmel! Ich weiß nicht, was für ein Geschöpf das ist, aber es ist sicher nicht auf den Inseln heimisch.\n\nWartet... Ich erinnere mich an eine schlagkräftige kleine Goblinfrau, die an den Blaufederklippen über uns nach dem Weg gefragt hat. Glaubt Ihr, sie weiß irgendetwas darüber?", sourceObjective = "Findet Harleen Hohnzirper an den Blaufederklippen.", completion = "Ein Wächter der Gelikyr hat gesagt, ich wäre hier? Hat er gesagt, ich würde ihm Geld schulden?", sourceObjectiveStatus = "unverified-source-field" }
quests[70782] = { id = 70782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baumkronenbanner" }
quests[70783] = { id = 70783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skaara" }
quests[70784] = { id = 70784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlassene Außenposten", description = "Dem nach zu schließen, was Ihr erzählt habt, scheint der Stein der Wachsamkeit in einem verlassenen Posten nordöstlich der Azurarchive zu sein. Das muss der Zelthrakaußenposten sein.\n\nTrefft mich dort, wenn Ihr ankommt, {name}, dann suchen wir gemeinsam nach dem Stein.", sourceObjective = "Trefft Euch mit Naleidea nahe dem Zelthrakaußenposten im Azurblauen Gebirge.", completion = "Ich wusste ja, dass dieser Ort verlassen ist, aber ich hätte nicht gedacht, dass er so... schmuddelig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[70785] = { id = 70785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stadt der Toten", description = "Eine antike Totenstadt kann nur eines bedeuten: das Verhüllte Ossuarium vor der Küste nördlich von Thaldraszus.\n\nEs ist gewaltig, entlegen und schwierig zu erreichen. Der perfekte Ort, um etwas zu verstecken. Ich bin nicht sicher, was wir dort finden werden, {name}. Aber Ihr könnt sicher sein, dass es uns nicht fröhlich empfangen wird.", sourceObjective = "Trefft Euch mit Naleidea am Verhüllten Ossuarium in Thaldraszus.", completion = "Gut, Ihr seid hier! Je eher wir anfangen, umso eher können wir gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70787] = { id = 70787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangen in einem dunklen Sturm" }
quests[70788] = { id = 70788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewickeltes Goldband", description = "<Das könnte etwas sein, wonach Emilia Bellersen sucht.>", sourceObjective = "Bringt den Gegenstand zu Emilia Bellersen.\n\nBereitgestellter Gegenstand:", completion = "Wundervoll. Ich lege es an einen sicheren Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[70789] = { id = 70789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fein geschnitzter Flügel", description = "<Das könnte etwas sein, wonach Emilia Bellersen sucht.>", sourceObjective = "Bringt den Gegenstand zu Emilia Bellersen.\n\nBereitgestellter Gegenstand:", completion = "Er ist so geschickt geschnitzt... Wir haben über die Zeitalter wirklich einige wundervolle Techniken verloren. Ich werde ihn nehmen und sicherstellen, dass er gut bewacht wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[70790] = { id = 70790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinerner Drachenzahn", description = "<Das könnte etwas sein, wonach Emilia Bellersen sucht.>", sourceObjective = "Bringt den Gegenstand zu Emilia Bellersen.\n\nBereitgestellter Gegenstand:", completion = "Er ist sehr alt, aber ich erkenne noch, was er ist... Ich werde sicherstellen, dass er gut aufbewahrt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[70791] = { id = 70791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaltgewaschene Drachenklaue", description = "<Das könnte etwas sein, wonach Emilia Bellersen sucht.>", sourceObjective = "Bringt den Gegenstand zu Emilia Bellersen.\n\nBereitgestellter Gegenstand:", completion = "Was muss das für eine gewaltige Statue gewesen sein. Und nun haben wir nur... dies. Aber immerhin haben wir etwas! Ich werde sicherstellen, dass sie katalogisiert wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[70805] = { id = 70805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kostbare Steinfragmente", description = "<Das könnte etwas sein, wonach Emilia Bellersen sucht.>", sourceObjective = "Bringt den Gegenstand zu Emilia Bellersen.\n\nBereitgestellter Gegenstand:", completion = "Ich frage mich, wie es wohl aussah, als es neu war? Mit Sicherheit beeindruckend. Vorerst bewahren wir es sicher in einer Kiste auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[70806] = { id = 70806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruchstück einer Skulptur", description = "<Das könnte etwas sein, wonach Emilia Bellersen sucht.>", sourceObjective = "Bringt den Gegenstand zu Emilia Bellersen.\n\nBereitgestellter Gegenstand:", completion = "Hm.\n\n<Emilia betrachtet das Stück aus verschiedenen Blickwinkeln.>\n\nVielleicht? Nein, ich weiß nicht, was es ist. Es ist jedoch alt und zweifellos wichtig. Auf in die Sammlung damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[70807] = { id = 70807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgeschrittene Ausgrabungswerkzeuge", sourceObjective = "Wir wissen Eure fortlaufende Hilfe für die Expedition zu schätzen. Um Euch für Eure Mühen zu danken, möchte ich Euch eines meiner fortgeschrittenen Ausgrabungswerkzeuge anbieten. Die übrigen Werkzeuge biete ich auch zum Verkauf an, also kommt gern wieder, wenn Ihr andere kaufen möchtet.\n\nVielen Dank, Abenteurer!", sourceObjectiveStatus = "unverified-source-field" }
quests[70808] = { id = 70808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anfängliche Geheimnisse der Drachen der Dracheninseln", sourceObjective = "Drachen haben mich schon immer faszniert. Hier zu sein ist also, als würde für mich ein Traum wahr. Ich habe schon viel über die erneuerten Protodrachen der Küste des Erwachens gelernt. Möchtet Ihr eines der Manuskripte sehen, die ich zusammengestellt habe? Ich habe viele Beobachtungen gemacht und würde diese auch gegen neue eintauschen!", sourceObjectiveStatus = "unverified-source-field" }
quests[70809] = { id = 70809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefere Geheimnisse der Drachen der Dracheninseln", sourceObjective = "Ich habe seit unserem letzten Gespräche große Fortschritte gemacht, Abenteurer! Bitte, wählt ein weiteres Manuskript, um Eurem erneuerten Protodrachen zu helfen, eine neue Fähigkeit zu lernen. Und vergesst nicht: wenn Ihr weitere kaufen wollt, sprecht einfach mit mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[70810] = { id = 70810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Geheimnisse der Drachen der Dracheninseln", sourceObjective = "Ich konnte meine Studien der anderen Drachen der Dracheninseln erweitern. Die bei den erneuerten Protodrachen am meisten verbreiteten roten Schuppen sind nicht nur auf ihre Art beschränkt. Jede der anderen großen Drachenarten kann ebenfalls rote Schuppen aufweisen. Bitte, wählt ein Manuskript für den Drachen, den Ihr vorzieht. Wenn Ihr weitere Manuskripte erwerben wollt, kommt gerne wieder vorbei!", sourceObjectiveStatus = "unverified-source-field" }
quests[70811] = { id = 70811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Professionelle Ausgrabungswerkzeuge" }
quests[70812] = { id = 70812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expeditionsumhänge", sourceObjective = "Ein guter Umhang kann der wichtigste Ausrüstungsgegenstand einer Expedition sein. Ihr habt Euch einen Umhang verdient. Sprecht mit mir, wenn Ihr einen weiteren erwerben möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[70813] = { id = 70813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schätze ausgraben", sourceObjective = "Die meisten Schätze hier in der Gegend verstecken sich im Boden: Uralte Artefakte, vielleicht sogar Wertgegenstände. Ihr werdet eine gute Schaufel brauchen, um dranzukommen. Doch Ihr habt Glück! Ich habe hier eine offizielle Schaufel der Expedition mit Eurem Namen drauf. Sucht nach aufgewühlter Erde und seht, was Ihr finden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[70814] = { id = 70814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Schätze öffnen", sourceObjective = "Dieser Ort verbirgt viele Schätze, die Ihr noch nicht gesehen habt, weil sie in Magie gebunden sind. Ich kann Euch beibringen, sie zu erkennen. Viele liegen tief in Höhlen versteckt oder in magisch verschlossenen Truhen in den vielen Ruinen dieses Landes. Viel Glück mit Eurer Suche!", sourceObjectiveStatus = "unverified-source-field" }
quests[70815] = { id = 70815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprenglizenz", sourceObjective = "Manche Ausgrabungen erfordern eine sanfte Hand, andere eine Stange Dynamit. Ich glaube, wir können Euch wohl zutrauen, den Unterschied zu kennen. Ihr könnt Euren ersten Sprengstoff kostenlos haben. Setzt ihn weise ein und enttäuscht mich nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[70816] = { id = 70816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Techniken der Schatzsuche" }
quests[70817] = { id = 70817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Drachenschuppenausrüstung", sourceObjective = "Die Drachenschuppenexpedition hat Zugriff auf einige der besten Handwerker in ganz Azeroth. Diese haben exzellente Ausrüstung hergestellt, die Euch bei der Erforschung helfen kann. Tatsächlich haben wir gerade eine Lieferung feinster Handschuhe erhalten. Seht Euch meine Waren an, wenn diese Euch interessieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[70818] = { id = 70818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Drachenschuppenausrüstung", sourceObjective = "Gerade ist eine Lieferung hochwertiger Beinrüstungen angekommen. Wenn Ihr etwas seht, das Euch gefällt, lasst es mich wissen, dann handeln wir.", sourceObjectiveStatus = "unverified-source-field" }
quests[70819] = { id = 70819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstung des berühmten Forschers", sourceObjective = "Ihr habt einige große Taten vollbracht, Abenteurer, und sie sind nicht unbemerkt geblieben. Die Expeditionsleitung hat mir die Genehmigung erteilt, Euch einen Satz unserer besten Rüstung auszuhändigen. Habt Dank für all Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[70820] = { id = 70820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die \"Haustiere\" des Basislagers", sourceObjective = "Argh! Ich dachte, ein Leben des Greifenbändigens hätte mich darauf vorbereitet, die widerspenstigen Biester der Dracheninseln zu zähmen. Aber diese Marmoni und Flatterkäfer bringen mich an meine Grenzen! Ich würde Euch liebend gern einen überlassen. Wenn Ihr noch einen wollt, kann ich Euch einen guten Handel anbieten!", sourceObjectiveStatus = "unverified-source-field" }
quests[70821] = { id = 70821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flatterlibellenreiten", sourceObjective = "Wer hätte gedacht, dass es Konsequenzen hat, sich um junge Flatterkäfer zu kümmern? Ihre Eltern, die Flatterlibellen, kamen auf der Suche nach ihnen her. Aber sie wollten nicht kämpfen, sondern haben lieber Nester gebaut. Genau wie ein Greif! Ich habe angefangen, sie auszubilden, und wer hätte es gedacht, es ist fast wie einen Greif zu reiten... wenn man sich einmal an diese summenden Flügel gewöhnt hat. Bei all der Hilfe, die Ihr hier geleistet habt, möchte ich Euch Eure erste Flatterlibelle kostenlos geben. Ich bilde Euch gerne noch eine aus, im Tausch gegen einige sehr spezielle Gegenstände.", sourceObjectiveStatus = "unverified-source-field" }
quests[70822] = { id = 70822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späher der verschollenen Expedition", sourceObjective = "Wir haben viele Späher ausgesandt, seit wir hier anlandeten, aber einige von ihnen sind nicht zurückgekehrt. Könntet Ihr die Augen nach ihnen offen halten, während Ihr die Gegend erforscht? Sie sind leicht an unserem Standardexpeditionsspäherpack zu erkennen. Oh, und falls Ihr irgendwelche Artefakte findet, bringt sie zu Katalogisiererin Jakes. Sie wird es Euch danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[70828] = { id = 70828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kompass des Wegfinders", sourceObjective = "Diese Lande sind riesig, und das Terrain steigt so sehr an, dass selbst die erfahrensten Fährtenleser sich verirren. Wenn Ihr uns zur Hand gehen wollt, müsst Ihr Euch irgendwie zurechtfinden. Nehmt diesen Kompass, der sollte helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70829] = { id = 70829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katalogisierungsexpeditionen" }
quests[70830] = { id = 70830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles fürs Klettern", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[70831] = { id = 70831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemütliche Forschung", sourceObjective = "Viele Stunden der Expeditionsarbeit verbringen wir... wie sage ich das? Auf unserem Hintern. Ich verstehe nicht, warum wir diese Zeit nicht gemütlicher machen können. Darum habe ich unsere neuen Verbündeten von der Archäologischen Akademie darum gebeten, uns ein paar schöne Kissen herzustellen. Ihr könnt Euch gern eins aussuchen, aber wenn Ihr mehr wollt, müsst Ihr dafür bezahlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[70832] = { id = 70832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einer von uns", sourceObjective = "Ihr seid genau die Art von Abenteurer, die wir in unserer Expedition brauchen, und wir sind froh, Euch zu haben! Als Zeichen unserer Dankbarkeit würde ich Euch gerne unseren Wappenrock überreichen. Damit könnt Ihr der Welt zeigen, was Ihr alles erreicht habt! Doch wir dürfen auch nicht unsere Wurzeln vergessen. Wenn Ihr ein Banner der Archäologischen Akademie oder Forscherliga wollt, kann ich die Euch ebenfalls anbieten. Habt Dank für alles, was Ihr für uns getan habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[70833] = { id = 70833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerüchte über juwelenbesetzte Welplinge", sourceObjective = "Habt Ihr die Geschichte des uralten Juwelenschleifers von den Dracheninseln gehört? Der Legende nach hatte er eine Technik, mit der er juwelenbesetzte Welplingstatuen erschuf, die zum Leben erwachten. Ich hielt das auch nur für eine Geschichte, aber dann wurde im Pack eines unserer gefallenen Späher diese Karte gefunden, die einen Hinweis auf juwelenbesetzte Welplinge enthält. Nehmt die Karte und findet heraus, ob sie zu dem Geheimnis führt, mit der man diese sagenumwobenen lebenden Statuen erschaffen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[70834] = { id = 70834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschichte mit Titel", sourceObjective = "Ich habe seit unserer Ankunft alle Taten und Artefakte katalogisiert, die jedes Mitglied zur Drachenschuppenexpedition beigetragen hat. Heute ist mir die schiere Größe Eurer Leistungen aufgefallen. Ich könnte nicht stolzer sein, Euch diesen prestigeträchtigen Titel zu verleihen und Euch diesen begehrten Gegenstand urzeitlicher Infusion zu überreichen, aus dem Ihr einen mächtigen Gegenstand herstellen lassen könnt. Geht hin und tragt ihn als eine Belohnung für Eure heldenhaften Anstrengungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70835] = { id = 70835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Robuste Expeditionsschaufel", sourceObjective = "<Boss Magor winkt Euch zu sich.>\n\nHallo, Schmied ich habe ein neues Muster, das Euch vielleicht interessiert!", sourceObjectiveStatus = "unverified-source-field" }
quests[70837] = { id = 70837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgung der Spur", description = "<Ermittler Erima betrachtet die Karte.>\n\nEs ist klar, was das X über dem Sitz der Aspekte bedeutet.\n\nAber es ist auch ein Kreis um das Neblige Tal herum gezeichnet. Vielleicht ist das das nächste Ziel der Rebellen? Oder eine Operationsbasis.\n\nEs gibt nur einen Weg, es herauszufinden. Trefft mich im Tal.", sourceObjective = "Trefft Ermittler Erima beim Nebligen Tal.", completion = "Das ist definitiv eine Operationsbasis. \n\nIm Nebligen Tal wimmelt es nur so vor Rebellen... und Primalisten!", sourceObjectiveStatus = "unverified-source-field" }
quests[70838] = { id = 70838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebellensache", description = "Der Sammelort der Rebellen... genau der Ort, den wir gesucht haben. Wie gut, dass der Leichtsinn ihres Saboteurs uns hierhergeführt hat.\n\nIch kann nicht fassen, dass meine Brüder sich dazu herabgelassen haben, mit den Primalisten gemeinsame Sache zu machen. Das können wir so nicht stehen lassen. Schaltet die Rebellen und ihre Primalistenfreunde aus, bevor sie weiteren Schaden anrichten können.", sourceObjective = "Tötet 10 Rebellen und Primalisten.", completion = "Ihr habt Euch gut geschlagen.\n\nDiese Rebellen sind nicht zu unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70839] = { id = 70839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Titanenrelikten", sourceObjective = "Seit dem Erwachen habe ich meine ganze Zeit dem Studium der Titanen gewidmet. Ihre Geschichte ist faszinierend. Welche Macht sie besessen haben müssen, um die Drachenschwärme erschaffen zu können! Es gibt so vieles, das wir noch über sie lernen können!\n\nWenn Ihr mir irgendwelche Relikte der Titanen bringen könntet, die Ihr auf den Dracheninseln findet, werde ich ein gutes Wort für Euch beim Valdrakkenabkommen einlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70840] = { id = 70840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Relikt der Titanen", progress = "Habt Ihr ein Relikt der Titanen gefunden?", completion = "Unglaublich! Dieses Relikt ist perfekt erhalten. Ich werde es sofort untersuchen.\n\nEure Bemühungen sind mehr als willkommen! Ich werde nicht vergessen, vor dem Valdrakkenabkommen gut von Euch zu sprechen.\n\nAlso, wo war ich? Ja, das passt perfekt hier hin..." }
quests[70841] = { id = 70841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Relikte der Titanen", progress = "Was habt Ihr heute für mich?", completion = "Wie habt Ihr so viele davon gefunden? Das ist eine wahrhafte Schatzkammer an Relikten! Eines Tages MÜSST Ihr mir Euer Geheimnis verraten.\n\nIhr habt unser Wissen über die Titanen einmal mehr erheblich vergrößert. Das Valdrakkenabkommen wird Euch wahrhaft bewundern!" }
quests[70842] = { id = 70842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprengorte", description = "Ich bin sicher, dass die Rebellen ihre Pläne für zukünftige Angriffe irgendwo dokumentieren. Wir müssen herausfinden, was sie vorhaben, bevor es zu spät ist.\n\nDurchsucht ihr Lager nach markierten Karten wie der, die wir in Valdrakken gefunden haben.", sourceObjective = "Sammelt Karten des Nebligen Tals.", progress = "Habt Ihr die Pläne der Rebellen gefunden?", completion = "Ich werde die Nachricht verbreiten, dass wir unsere Sicherheitsvorkehrungen an diesen Orten erhöhen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70843] = { id = 70843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runensteine ruinieren", description = "<Dieser Runenstein ist dem anderen, den die Rebellen in Valdrakken platzieren wollten, erstaunlich ähnlich.\n\nDieser Stein ist noch nicht fertig, aber Ihr entdeckt ganze Lager von vollendeten Runensteinen in einiger Entfernung.\n\nWenn Ihr diese Lager zerstört, können die Rebellen die Runensteine nicht zum Einsatz bringen.>", sourceObjective = "Zerstört die Lager mit flammenden Runensteinen.", completion = "Ich konnte die Erschütterung der Explosionen bis hierher spüren.\n\nValdrakken ist dank Eurer Bemühungen jetzt sicherer.", sourceObjectiveStatus = "unverified-source-field" }
quests[70845] = { id = 70845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Tyrs Fußstapfen", description = "Hüter Tyr hat alle Eventualitäten bedacht. Er vermutete, dass die Handwerker des Reiches eines Tages ermächtigt werden müssen, und so erschuf er die Innovationsmaschine. Sie verfügt über die Fähigkeit, ein einzigartiges Handwerksmaterial herzustellen, das einem Gegenstand Wissen verleiht, das jenseits der Fähigkeiten des sterblichen Verstands liegt.\n\nUm sicherzugehen, dass seine Maschine nicht in die falschen Hände gerät, erschuf er mich, um zu überwachen, wer ihre Macht sucht. Nur, wer ihr würdig ist, wird das volle Potenzial der Maschine erwecken können. \n\nSeid Ihr der Herausforderung gewachsen?", sourceObjective = "Findet die erste Herausforderung von Tyr im Azurblauen Gebirge.", completion = "<Ihr habt das Gefühl, die Statue würde auf Eure Anwesenheit reagieren, als ihr Mechanismus langsam erwacht und sie mit Leben erfüllt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[70847] = { id = 70847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralter Obsidiananhänger", description = "<Krallenpirscherin Kavia könnte das haben wollen.>", sourceObjective = "Bringt den Gegenstand zu Krallenpirscherin Kavia.\n\nBereitgestellter Gegenstand:", completion = "Es ist noch intakt. Hoffentlich bringt es seinem nächsten Besitzer mehr Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[70848] = { id = 70848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergessenes Drachenwappen", description = "<Exadria könnte das haben wollen.>", sourceObjective = "Bringt den Gegenstand zu Exadria.\n\nBereitgestellter Gegenstand:", completion = "Dieses Wappen gehörte einst den ersten Drachen, die in dieser Zitadelle gelebt haben. Wir werden es an einem Ehrenplatz ausstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70849] = { id = 70849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das schreit nach einem Spezialisten", description = "Lubbins geht es schon viel besser, aber ich glaube, er braucht noch mehr Hilfe.\n\nVor einer Weile habe ich eine super kluge Forscherin der Drachenschuppenexpedition namens Haniko getroffen, die ständig mit Protodrachen arbeitet. Sie ist auch eine Kampfhaustiertrainerin. Ich wette, sie kann Lubbins besser helfen!\n\nich glaube, sie wollte zur Küste des Erwachens. Wenn Ihr dort hingeht, werdet Ihr sie sicher finden.\n\nIch bin so froh, dass ich Euch helfen konnte!\n\n<Sie winkt fröhlich.>\n\nLebt wohl! Viel Glück, Lubbins!", sourceObjective = "Sprecht mit Haniko im Wildreservat an der Küste des Erwachens.", completion = "Es war klug von Flicki, Euch herzuschicken. Ich habe mein Leben lang mit Protodrachen gearbeitet.\n\nIch weiß nicht, ob irgendjemand in Azeroth mehr über sie weiß als ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[70850] = { id = 70850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maldra steht das Wasser bis zum Hals", description = "Ausgezeichnete Arbeit. Während Ihr für Unruhe gesorgt habt, habe ich das Lager ausgekundschaftet. Ich hätte nicht erwartet, meine alte Freundin Maldra Flammenzunge hier zu finden.\n\nIch wusste, dass sie vermisst wird, aber den Gerüchten zufolge hieß es, sie hätte sich den Rebellen angeschlossen. Soweit ich sehe, ist sie aber ihre Gefangene!\n\nWir können sie hier nicht zurücklassen. Rettet sie vor der Drachenbrut, die sie gefangen hält!", sourceObjective = "Rettet Maldra vor Orian Dunkelwasser.", completion = "Danke, dass Ihr meine Freundin gerettet habt. Ich stehe in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[70851] = { id = 70851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extreme Wildheit im Blut", description = "Es gibt vieles, was Ihr wissen müsst. Lasst uns reden, dann können wir entscheiden, was das Beste für Lubbins ist.", sourceObjective = "Erfahrt, was Lubbins von Haniko braucht.", completion = "Gut! An die Arbeit, {name}.\n\nBevor Ihr geht, nehmt diese polierten Haustierglücksbringer. Kampfhaustiertrainer tauschen diese Glücksbringer gerne gegen nützliche Vorräte, haltet also die Augen offen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70853] = { id = 70853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Freund für Lubbins", description = "Wie wir bereits besprochen haben, braucht Lubbins zwei Dinge: einen Kumpel und einen Kampf.\n\nIch glaube, dass wir ihm beides auf einen Schlag besorgen können.\n\nDiese Gegend ist ein erstklassiges Paarungsgebiet für Scheulibellen. Ihr solltet hier im Gebiet viele davon finden können, wenn Ihr Euch ein wenig umschaut.\n\nAber denkt dran, Ihr müsst sie erst schwächen, bevor Ihr sie mit Eurer Falle fangen könnt.\n\nKommt zurück, wenn Ihr eine habt. Nach dem Kampf wird sie vermutlich etwas angeschlagen sein, aber ich habe ein paar Kampfübungssteine, die ihr direkt wieder auf die Beine helfen werden!", sourceObjective = "Fangt eine Scheulibelle im Wildreservat an der Küste des Erwachens.", completion = "Gut gemacht. Ich glaube, diese Kampfsteine sind genau das, was Euer neues Haustier braucht.\n\nWisst Ihr was? Nehmt doch gleich noch ein paar polierte Haustierglücksbringer mit.\n\nHabe ich schon erwähnt, dass Ihr die gegen tolle Sachen eintauschen könnt? Das könnt Ihr nämlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[70854] = { id = 70854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie ist es gelaufen?", description = "Das habt Ihr toll gemacht, {name}. Lubbins geht es schon viel besser und er ist bei bester Laune.\n\nJyhanna wird das wissen wollen, also geht schon zurück und überbringt ihr die tollen Neuigkeiten!", sourceObjective = "Kehrt zu Jyhanna in der Welpenkrippe in Valdrakken zurück.", completion = "Ich bin so froh, dass Ihr Lubbins helfen konntet.\n\nVielleicht könnt Ihr ja noch einem anderen Tier helfen, das ich gerettet habe. Sein Name ist Herr Hupe. Er ist richtig süß und ich glaube, Ihr würdet gut zueinander passen.\n\nWas sagt Ihr? Habt Ihr noch Platz für ein weiteres Haustier?", sourceObjectiveStatus = "unverified-source-field" }
quests[70856] = { id = 70856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie mit Feuer", description = "Diese ekligen Spinnen legen ihre Eier in Leichen ab.\n\nUnd manchmal in Lebendigen.\n\nWir haben einige Leichen der Splitterflammen gesehen, die ihnen zum Opfer fielen.\n\nWenn wir hier überleben und die Splitterflammen besiegen wollen, dürfen wir nicht zulassen, dass die Eier schlüpfen.\n\nNehmt diese Fackel. Sie ist mit der Macht von Luft und Feuer verzaubert. Richtet sie auf alles, was Ihr verbrennen wollt, und sie erledigt den Rest.\n\nDie Tuskarr machen keine halben Sachen mit Spinnen. Ich bin immer vorbereitet.", sourceObjective = "Vernichtet 10 infizierte Leichen mit der Flammenwerferfackel.", completion = "Gute Arbeit. Das verschafft uns etwas Raum zum Atmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70858] = { id = 70858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück ins Getümmel!", description = "Na gut, das Gegengift ist fertig. Ich werde Alia stützen, Ihr gebt den Inhalt der Phiole in ihren Mund.\n\nHoffentlich überlebt sie... Wir brauchen ihre Magie, um dieses Artefakt zu finden.", sourceObjective = "Wendet das eiskalte Gegengift auf Alia Segelstrahl an.", completion = "Ich danke Euch... Ich dachte, ich würde sterben, bevor ich dieses Artefakt finde.", sourceObjectiveStatus = "unverified-source-field" }
quests[70859] = { id = 70859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was der Wächter weiß", description = "Ich begrüße Eure Hilfe, {class}. Ich war die Magierin der Kirin Tor, die dieses Artefakt, Valthrux, und die Pläne der Splitterflammen als Erste gefunden hat.\n\nDie Wiederbeschaffung und das Studium dieses angeblich empfindungsfähigen und mächtigen Artefakts ist von oberster Dringlichkeit. Und ich schwöre, ich werde diejenige sein, die es tut.\n\nDie Splitterflammen müssen raten, wo es sein könnte, aber ich habe mit Magie einen Weg für uns gefunden.\n\nEs gibt einen verderbten Wächter in der Nähe, der einen magischen Splitter besitzt, der mit Valthrux verbunden ist. Ich kann ihn nutzen, um den Rest des Artefakts zu finden.", sourceObjective = "Beschafft den flüsternden Splitter von Edavix, dem verderbten Wächter.", progress = "Habt Ihr den Splitter gefunden?", completion = "Gebt ihn mir! Schnell!\n\nHört Ihr auch das Flüstern?", sourceObjectiveStatus = "unverified-source-field" }
quests[70867] = { id = 70867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bannschuppenfeste" }
quests[70871] = { id = 70871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischernetz von Iskaara", description = "Ich sehe, Ihr versteht Euch gut mit den Dorfbewohnern.\n\n\n\nIhr wollt mehr darüber lernen, wie wir angeln, sagt Ihr? Gut, zuerst einmal angelt niemand mit bloßen Händen. Ich kann Euch ein gutes, starkes Netz herstellen, das eines Tuskarrs der Iskaara würdig ist.", sourceObjective = "Bringt Tavio Materialien und lasst sie ein Fischernetz von Iskaara herstellen.", progress = "Habt Ihr passende Materialien gefunden? Ich brauche den stärksten Tang und einige gute Steine mit Loch.", completion = "Hier ist Euer Fischernetz von Iskaara. Setzt es weise ein und nehmt nie mehr aus dem Kreislauf des Lebens, als Ihr zum Überleben braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[70873] = { id = 70873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserfällen auf der Spur", description = "Die wahre Bedrohung liegt in der Glutschieferhöhle. Dort werden diese Runensteine gemeißelt und mit Urfeuer erfüllt.\n\nIhr habt zweifellos die lodernde Flammenwand entdeckt, die den Eingang versperrt. Ich kann sie nicht entzaubern, aber vielleicht kann ich auf andere Weise helfen. Ich glaube, dass wir mit der richtigen Anwendung von Wasserfall unversehrt hindurchgehen können.\n\nSammelt Wasserpartikel von den Elementaren in der Nähe.", sourceObjective = "Sammelt 35 Wasserfallpartikel.", progress = "Wir werden diese Partikel brauchen, um Euch sicher in die Glutschieferhöhle zu bringen.", completion = "<Maldra untersucht die Wasserfallpartikel.>\n\nJa, die sollten funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[70874] = { id = 70874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Feuerwand durchbrechen", description = "Die Rebellen in der Höhle wurden mit einem elementaren Segen erfüllt, der es ihnen erlaubt, die Flammenwand sicher zu durchschreiten. Ich kann Euch denselben Segen gewähren.\n\nKeine Sorge, ich habe diesen Vorgang oft genug beobachtet. Ich sollte ihn problemlos imitieren können.", sourceObjective = "Erhaltet Maldras elementaren Segen.", progress = "Wie fühlt Ihr Euch?", completion = "Keine Angst. Dieses kalte, klamme Gefühl geht wieder vorbei.", sourceObjectiveStatus = "unverified-source-field" }
quests[70875] = { id = 70875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlimmer geht's nicht", description = "Die Rebellen in der Glutschieferhöhle sind unerschütterlich loyal gegenüber den Primalisten und stellen daher die größte Gefahr für Valdrakken dar.\n\nEliminiert sie und alle Elementare, die sie entfesselt haben.", sourceObjective = "Tötet 3 Rebellen und 4 Elementare in der Glutschieferhöhle.", completion = "Gut gemacht, {name}.\n\nDenjenigen, die den Primalisten folgen, darf nicht zugestanden werden, dass sie Chaos und Zerstörung verbreiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[70876] = { id = 70876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmentierte Fokusse", description = "Wenn Maldra die Wahrheit sagt, stellen die Rebellen die Runensteine in der Glutschieferhöhle her.\n\nAußerdem wissen wir, von der Natur dieser Geräte ausgehend, dass Fokusse der Primalisten involviert sind.\n\nZerstört die Fokusse. Ihr werdet sie erkennen, wenn Ihr sie seht.\n\nDie Rebellen dürfen nicht noch mehr Waffen der Zerstörung herstellen.", sourceObjective = "Zerstört 4 Primalistenfokusse in der Glutschieferhöhle.", completion = "Ohne diese Fokusse können die Rebellen ihre Runensteine nicht länger mit explosiven Flammen erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70877] = { id = 70877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quaken in der Zeit", description = "<Das Entchen ist verzweifelt und quakt leise vor sich hin, während seine Augen ängstlich umherblicken.>\n\n<Vielleicht wissen die Ökologen, wie man ihm helfen kann?>", sourceObjective = "Bringt das Entchen in der Blase zurück ins Ökologenlager.", progress = "<Tharu redet beruhigend auf das Entchen in der Blase ein.>\n\nSchhh, nicht weinen, mein Kleines.\n\nWir großen, starken Ökologen werden auf Euch aufpassen! Und {name} natürlich auch.", completion = "Danke, dass Ihr uns Gänseblümchen gebracht habt. Es sind jetzt schon zwei, also müssen es noch mehr sein. Haltet die Augen offen, wenn Ihr Euch das nächste Mal auf den Weg macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[70878] = { id = 70878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerring", description = "Die Primalisten haben in den tiefsten Abzweigungen der Glutschieferhöhle ein feuriges Portal errichtet, aus dem sie Elementare entfesseln.\n\nIch kann es schließen, aber meine Handlungen werden zweifellos den Zorn von dem wecken, was auch immer auf der anderen Seite wartet. Einschließlich dem Wiedergänger Magmaticus, dem die Primalisten helfen.\n\nIch werde Euren Schutz brauchen, wenn wir sie aufhalten wollen.", sourceObjective = "Beschützt Maldra Flammenzunge, während sie das Portal der Primalisten schließt.", completion = "Nicht schlecht, {name}!\n\nMaldra hat mir die Einzelheiten Eurer Heldentaten schon erzählt.", sourceObjectiveStatus = "unverified-source-field" }
quests[70879] = { id = 70879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht über die Rebellen", description = "Ich bin beeindruckt, was Ihr heute geschafft habt. Findet Ihr nicht auch, {name}?\n\nWir haben die niederträchtigen Machenschaften dieser mit den Primalisten verbündeten Rebellen erfolgreich beendet. Zumindest für den Moment. Wir werden in Zukunft die Augen nach Dissidenten offen halten müssen.\n\nKehrt zu Hauptmann Drine zurück, sobald Ihr könnt. Sie wird unseren Bericht hören wollen.", sourceObjective = "Trefft Hauptmann Drine im obersten Stockwerk des Sitzes der Aspekte.", completion = "Willkommen zurück, {name}.\n\nMeine Augen und Ohren haben mir gerade die guten Nachrichten überbracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[70880] = { id = 70880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochen mit Finesse", sourceObjective = "Hallo. Darf ich Euch eine Gabel anbieten? Oder vielleicht etwas Tee? \n\nEs ist mir eine Freude, so viele Leute in Valdrakken zu sehen. Ich bin sicher, Ihr werdet uns wunderbar aushelfen. Wenn Ihr ein passendes Messer zu Eurer Gabel braucht, lasst es mich wissen, dann handeln wir!", sourceObjectiveStatus = "unverified-source-field" }
quests[70881] = { id = 70881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vierte Herausforderung von Tyr: Einfallsreichtum", description = "Die Maschine ist kurz davor, ihr volles Potenzial zu erreichen. Alles, was sie jetzt noch braucht, ist ein Energiekern, um die zugeführte Essenz effizienter zu nutzen.\n\nTyr hinterließ Hüter Irideus Wissen über solche Geräte. Begebt Euch in die Hallen der Infusion und sucht ihn. Er wird Euch sicher bei allem helfen, was Ihr braucht.", sourceObjective = "Beschafft Euch einen Energiekern von Hüter Irideus und bezwingt den urtümlichen Tsunami in den Hallen der Infusion.", progress = "Ihr habt Hüter Irideus gefunden?", completion = "Vielleicht waren es diese Feinde der Ordnung, gegen die sich Hüter Tyr schützen wollte. Trotzdem können wir den Verlust von Hüter Irideus dennoch in einen Sieg verwandeln. Mit seinem Energiekern können wir vielleicht die Maschine antreiben, und ein Teil von ihm wird immer als Tyrs Schöpfung weiterleben.\n\n<Ihr könntet schwören, dass Ihr im Gesicht der Maid kurz Traurigkeit erkannt habt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[70882] = { id = 70882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmvorräte", sourceObjective = "Grüße, {class}. Ihr habt Euren Wert gegenüber dem Valdrakkenabkommen bewiesen. Nehmt einige Vorräte als Unterstützung Eurer Sache. Enttäuscht uns nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[70883] = { id = 70883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grüner Daumen", description = "Grüße, <Sterblicher/Sterbliche>, ich habe etwas von unserem Chefgärtner Gryrmpech gehört. Und zwar, dass die Gärten im Chaos versinken, aber ich weiß nicht, ob das nicht normal ist.\n\nEr hat mir versichert, dass er alles im Griff hat... also eigentlich hat er gesagt, er hätte alles \"auf der Schaufel\", deswegen bin ich mir nicht sicher, was er genau meint, aber ich glaube, er wird es Euch verraten. Sucht ihn bitte auf, dann kann er Euch über die Situation aufklären.", sourceObjective = "Sucht Gryrmpech in den Gärten der Einigkeit auf.", completion = "Ein Gartenhüter braucht eigene Waffen. Lasst mich Euch für den Kampf ausrüsten. \n\nIch habe mehr Instrumente des Krieges, wenn Ihr welche braucht. Ich weiß Eure Hilfe beim Zähmen dieser Wildnis zu schätzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[70884] = { id = 70884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückeroberung", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[70885] = { id = 70885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhmvorräte", sourceObjective = "Grüße, {class}. Ihr habt Euren Wert gegenüber dem Valdrakkenabkommen bewiesen. Nehmt einige Vorräte als Unterstützung Eurer Sache. Enttäuscht uns nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[70886] = { id = 70886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DAS nenne ich Drachenrennen!", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[70887] = { id = 70887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gefühl der Freiheit", sourceObjective = "Meine kleineren Artgenossen können jetzt ungehindert die Dracheninseln erforschen, und es erfüllt mich mit Freude, wie sie aufblühen und ihre neuen Erfahrung genießen. \n\nIch würde Euch gerne beibringen, wie sie sich Euch und anderen gegenüber ausdrücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[70888] = { id = 70888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schulter an Schulter mit den Besten", sourceObjective = "Tag und Nacht an der Ausrüstung unserer Streitkräfte zu arbeiten ist keine einfache Aufgabe. Es ist harte Arbeit, aber sie macht mir Spaß. Und ich habe gehört, dass Ihr ein wahrer Segen für unsere Bemühungen seid.\n\nNehmt Euch eines meiner Rüstungsteile, als Zeichen meiner Dankbarkeit. Nur eines. Wenn Ihr noch eines braucht, verlange ich etwas im Gegenzug. \n\nEntscheidet Euch schnell. Ich habe zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[70889] = { id = 70889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeiten für die Erfahrung", sourceObjective = "Ihr seid zurückgekehrt, Alchemist? Ich habe Euch aus der Ferne beobachtet und ich habe gesehen, wie beharrlich Ihr Euch angestrengt habt.\n\nUm Eure Anstrengungen zu belohnen und Euch zu einem Experten auszubilden, übergebe ich Euch diese zusätzlichen Notizen unserer Alchemiemeister. Studiert sie sorgfältig. Nur durch Übung könnt Ihr Euren Platz neben den Meistern einnehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[70890] = { id = 70890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Abenteuer!", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[70891] = { id = 70891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dazugehören", sourceObjective = "Wenn Ihr in dieser Stadt arbeiten oder leben wollt, MÜSST Ihr Euch anpassen. \n\nIch werde Euch ein Gewand nach der neuesten Mode schneidern, Ihr dürft Euch sogar die Farbe aussuchen! Was meint Ihr, welcher Schwarm betont Eure Augen am besten? \n\nWenn Ihr Euch nicht für einen entscheiden könnt, dürft Ihr Euch gerne mehrere Monturen zulegen, aber nur gegen einen Handel, versteht sich!", sourceObjectiveStatus = "unverified-source-field" }
quests[70892] = { id = 70892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beginn des Handwerks", sourceObjective = "Ihr wünscht, von unseren Alchemiemeistern zu lernen?\n\nIhr müsst Eure Fertigkeiten verbessern, bevor Ihr sie um Rat fragt. Aber seid ohne Sorge. Ich habe einige Notizen, die sie angehenden Alchemisten zur Verfügung stellen. \n\nMit diesen Notizen könnt Ihr Eure ersten Erfahrungen sammeln! Übt, ihre Inhalte herzustellen, und vielleicht werden sie Euch dann eines Tages mehr Wissen anvertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70893] = { id = 70893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinschaftliches Festmahl", description = "Unser gemeinschaftliches Festmahl findet GENAU JETZT statt! Dabei trägt jeder etwas bei und wir machen die beste Suppe, die wir kochen können.\n\nIhr könntet mitmachen!", sourceObjective = "Führt 5 Aufgaben beim gemeinschaftlichen Festmahl aus", progress = "Ihr habt Glück, dass Ihr für das Festmahl hier wart. Das tun wir nur sechs oder sieben Mal pro Tag!", completion = "Wenn alle zusammenarbeiten, schmeckt die Suppe GROSSARTIG!\n\nIhr solltet sie kosten, wenn sie fertig ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[70895] = { id = 70895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modisches Gleiten", sourceObjective = "Ah, Sterblicher. Geschichten über Eure Abenteuer verbreiten sich wie ein Lauffeuer in der Stadt. Alle blicken auf Euch, wenn Ihr und Euer Drachenfreund über den Himmel gleitet. \n\nLasst uns weiter über die erstaunliche Vielfalt an Ausdrucksformen unter den Drachen sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70896] = { id = 70896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergesst nicht, zu Taillen", sourceObjective = "Mein Meister Furorion hat mich in dieser großen Schmiede stationiert. Er hat mich angewiesen, Abenteurern wie Euch zur Hand zu gehen.\n\nIch habe einige gute Gürtel anzubieten. Lasst meinen Boss wissen, dass ich meine Arbeit mache, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[70897] = { id = 70897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg zur Mündigkeit", sourceObjective = "Ihr seid zurückgekehrt. Die Arbeit wird nicht weniger. Tatsächlich wird mein Können mehr denn je gefordert. \n\nWollt Ihr also den ganzen Tag da herumstehen oder lieber einen meiner makellosen Helme aussuchen? Ja, ich weiß, wie gut sie sind. \n\nWollt Ihr etwas anderes kaufen? Wenn Ihr Euch nicht entscheiden könnt, muss ich wieder an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[70899] = { id = 70899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fünfte Herausforderung von Tyr: Genialität", description = "Da dies nicht der Energiekern ist, den wir finden sollten, muss er auf die Energien der Maschine eingestellt werden. Die Resonanzfrequenzen der Bewohner von Tyrhold sollten das volle Potenzial des Kerns wieder entfalten.\n\nAuch wenn ich nicht wirklich weitere meiner Artgenossen opfern will, so glaube ich doch, dass diese Herausforderung nur auf diesem Weg gelöst werden kann.", sourceObjective = "Stimmt Irideus' Energiekern mit der titanischen Energie von Tyrhold ab.", completion = "Ihr habt die letzte Herausforderung abgeschlossen. Obwohl sie Verluste gefordert hat, glaub ich, dass es für ein höheres Ziel war. Hüter Tyr wollte, dass Ihr erfolgreich seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[70900] = { id = 70900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Innovation der Maschine", description = "Tyr glaubte, dass die Innovationsmaschine für kommende Schlachten unentbehrlich sei. \n\nIhr habt Euch als würdig erwiesen und alle Herausforderungen überwunden, die Euch gestellt wurden. Ihr dürft das volle Potenzial der Maschine jetzt erwecken.", sourceObjective = "Setzt den neu abgestimmten Energiekern in die Innovationsmaschine ein.", progress = "<Die Maschine summt leise, als Ihr Euch nähert.>", completion = "<Nach dem Einsetzen des neuen Kerns pulsiert die Maschine vor warmer Energie.>", sourceObjectiveStatus = "unverified-source-field" }
quests[70901] = { id = 70901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Kreaturensammlung", sourceObjective = "Grüße, Sterblicher. Ich kümmere mich um das Gelände und die Kreaturen, die es ihre Heimat nennen, sogar um verirrte Protowelpen. \n\nLeider gibt es hier viel mehr Protowelpen, als ich je versorgen könnte. \n\nHm, Ihr seht mir verantwortungsbewusst aus. Wollt Ihr Euch gerne um einen kümmern? Und wenn Ihr später einen Begleiter als... äh... Eure Begleitung sucht, kommt wieder zu mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[70902] = { id = 70902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeiten für die Erfahrung", sourceObjective = "So wie es aussieht, habt Ihr hart gearbeitet, {name}. Wartet, solltet Ihr Ingenieure nicht klüger statt härter arbeiten? Vielleicht seid Ihr doch nicht für die Ingenieurskunst geeignet!\n\nIch ziehe Euch nur auf, {race}. Hier. Die Ingenieursmeister haben Euch weitere Notizen hinterlassen, die Euch dabei helfen, Eure Fertigkeiten weiter zu verbessern. Sie haben mir versprochen, dass ihre Aufzeichnungen diesmal ausführlicher sind, aber das werdet Ihr bald besser wissen als ich. Viel Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[70903] = { id = 70903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Titanen führen", sourceObjective = "Die Studien von Tyrhold und allen Artefakten der Titanen auf den Dracheninseln sind unerlässlich für unsere Bemühungen im Kampf gegen die Primalisten. \n\nDie Waffen, die sie hinterlassen haben, sind besonders wichtig. Ich habe erst vor Kurzem ein großes Lager entdeckt und möchte Euch eine davon als Dank für Eure Bemühungen überreichen. \n\nNachdem ich meinen Fund katalogisiert habe, kann ich gerne weiter mit Euch handeln, aber ich würde Euch bitten, mir Materialien für meine Forschungen zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70904] = { id = 70904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abwechslung ist die Würze des Lebens", sourceObjective = "Drachen sind uralte Wesen, so verschieden in unserem Äußeren wie Eure sterblichen Völker. \n\nIch könnte Euch mehr über unsere Abstammung und die unterschiedlichen Erscheinungsbilder erzählen, die ich gesehen habe.\n\nVielleicht möchte der Drache, auf dem Ihr fliegt, meine Geschichten hören und die Möglichkeiten erfahren, die sich ihm bieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[70905] = { id = 70905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegt mit unseren Farben", sourceObjective = "Wir Drachkin tragen die Farben unseres Schwarms mit Stolz! Wie ihr an meinem Gewand... und meinen Schuppen sehen könnt.\n\nAber jetzt können Schuppenträger und Schuppenlose gleichermaßen zeigen, dass sie zu unseren erneuerten Schwärmen stehen. Legt einen Wappenrock an und tragt ihn mit Stolz!", sourceObjectiveStatus = "unverified-source-field" }
quests[70907] = { id = 70907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maruuk-Jagden" }
quests[70908] = { id = 70908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maruuk-Jagden" }
quests[70909] = { id = 70909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeiten für die Erfahrung", sourceObjective = "An den dunklen Flecken auf Eurer Rüstung sehe ich, dass Ihr hart gearbeitet habt. Und Ihr habt auch die Aufmerksamkeit unsere Meister erregt! Aufgrund Eurer Arbeiten wohlgemerkt, nicht wegen der Sauberkeit Eurer Rüstung, nur damit das klar ist...\n\nAls Belohnung haben sie Euch weitere Notizen hinterlassen, die Euch beim Lernen helfen sollen. Studiert sie und übt weiter, und vielleicht werdet Ihr eines Tages sogar die Meister übertreffen. Viel Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[70910] = { id = 70910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse in Papier und Glas", sourceObjective = "Willkommen in meinem Geschäft! Ich habe viele neue Gegenstände, die Euch interessieren könnten. \n\nEure Bemühungen auf den Dracheninseln sind das Thema Nummer eins auf dem Markt, ich möchte Euch also eines dieser Dinge schenken. \n\nWenn Ihr noch weitere haben wollt, können wir gerne um sie handeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[70911] = { id = 70911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gepanzert und bereit", sourceObjective = "Ah, der edle {class} kehrt vom Pfad des Abenteuers zurück.\n\nDie Schuppen eines Drachen mögen dick und hart sein, aber es wäre unverantwortlich, unsere Jungen ungeschützt in die Schlacht zu schicken. Erlaubt mir, Euren Drachen mit seiner ersten Rüstung auszustatten.\n\nKommt wieder zu mir, wenn Ihr ein weiteres Set kaufen wollt. Vielleicht könnt Ihr auch Rüstungen auf den Inseln finden. Klare Himmel und starke Winde!", sourceObjectiveStatus = "unverified-source-field" }
quests[70912] = { id = 70912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die hohen Ansprüche des Abkommens", sourceObjective = "Das Banner eines Drachenschwarms zu tragen bedeutet, dass Ihr seine Sache unterstützt. \n\nWählt ein Banner und tragt es mit Stolz. Wenn Ihr später ein weiteres erwerben wollt, kommt wieder zu mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[70913] = { id = 70913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Kleid zu tragen", sourceObjective = "Ihr seid von Euren Abenteuern zurück, wie? Ihr seid wohl nicht ganz unversehrt davongekommen. Ihr könnt bestimmt einige neue Schulterstücke brauchen.\n\nWenn Ihr nichts findet, das Euch gefällt, könnt Ihr eine Spezialanfertigung bestellen. Dafür brauche ich spezifische Materialien, aber das sollte für jemanden von Euren Fähigkeiten kein Problem sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[70914] = { id = 70914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bandbreite der Drachenwaffen", sourceObjective = "Ah, {class}. Willkommen zurück in unserer Schmiede. Wir alle haben Geschichten über Eure großen Taten im Dienste von Valdrakken gehört. \n\nWir Schmiede dienen der Sache auf unsere Weise. Und einen Helden wie Euch meine besten Waffen schwingen zu sehen, wäre in der Tat ein Ehre!", sourceObjectiveStatus = "unverified-source-field" }
quests[70915] = { id = 70915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der krönende Erfolg", sourceObjective = "Aber hallo, Ihr macht Euch wirklich einen Namen. Zumindest behauptet das der Boss. \n\nIch für meinen Teil stelle den ganzen Tag Helme her. Die besten der Inseln! Seht sie Euch an. Meine Preise sind fair. \n\nAlso... im Vergleich.", sourceObjectiveStatus = "unverified-source-field" }
quests[70916] = { id = 70916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bekannt und berühmt", sourceObjective = "Grüße, lieber {name}. Eure Dienste für Valdrakken sind unübertroffen. \n\nAlle sollen wissen, dass Ihr ein wahrer Verbündeter der Drachen seid!\n\nUnd um Euer Ansehen und Eure Taten zu untermauern, gebe ich Euch außerdem eine urzeitliche Infusion. Nehmt sie und stellt etwas Großartiges damit her, mit dem wir weiterhin unsere Feinde vernichten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[70917] = { id = 70917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Schulter zum Anquaken", description = "<Das Entchen ist voller nervöser Energie. Es scheint unbedingt aus seiner misslichen Lage entkommen zu wollen.>\n\n<Vielleicht wissen die Ökologen, wie man ihm helfen kann?>", sourceObjective = "Bringt das Entchen in der Blase zurück ins Ökologenlager.", progress = "<Tharu redet beruhigend auf das Entchen in der Blase ein.>\n\nSchhh, nicht weinen, mein Kleines.\n\nWir großen, starken Ökologen werden auf Euch aufpassen! Und {name} natürlich auch.", completion = "Danke, dass Ihr Löffelchen zu uns gebracht habt - diese Entenküken werden immer mehr! Haltet die Augen nach mehr von ihnen offen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70918] = { id = 70918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quak um dein Leben", description = "<Das Entchen quakt verzweifelt. Wenn ihm nicht jemand hilft, werden die Gorlocs sicherlich ärgerlich!>\n\n<Vielleicht wissen die Ökologen, wie man ihm helfen kann?>", sourceObjective = "Bringt das Entchen in der Blase zurück ins Ökologenlager.", progress = "<Tharu redet beruhigend auf das Entchen in der Blase ein.>\n\nSchhh, nicht weinen, mein Kleines.\n\nWir großen, starken Ökologen werden auf Euch aufpassen! Und {name} natürlich auch.", completion = "Quaker ist ein ganz schön lebhafter kleiner Kerl, oder? Danke, dass Ihr ihn zu uns gebracht habt - es kann jetzt nicht mehr allzu viele von ihnen geben!", sourceObjectiveStatus = "unverified-source-field" }
quests[70919] = { id = 70919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quaken und Heilen", description = "<Das Entchen ist schon so lange in der Blase, dass es fest eingeschlafen ist. Es quakt leise, während es schnarcht.>\n\n<Vielleicht wissen die Ökologen, wie man ihm helfen kann?>", sourceObjective = "Bringt das Entchen in der Blase zurück ins Ökologenlager.", progress = "<Tharu redet beruhigend auf das Entchen in der Blase ein.>\n\nSchhh, nicht weinen, mein Kleines.\n\nWir großen, starken Ökologen werden auf Euch aufpassen! Und {name} natürlich auch.", completion = "Käse und Quaker, hehe... Ich würde sagen, das sind so ziemlich alle Entchen in Blasen, die wir betreuen können, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[70920] = { id = 70920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A > B Reward Test (Med Health)" }
quests[70921] = { id = 70921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A > B Reward Test (High Health)" }
quests[70922] = { id = 70922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A > B Reward Test (Mini Boss Steps)" }
quests[70924] = { id = 70924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinschaftliches Festmahl" }
quests[70925] = { id = 70925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinschaftliches Festmahl" }
quests[70926] = { id = 70926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Totems", progress = "Seid Ihr hier, um unsere Totems zurückzubringen?", completion = "Ah! Unsere Totems sind uns sehr wichtig. Ihr habt unseren Dank dafür, dass Ihr sie zurückgebracht habt, Jungspund." }
quests[70927] = { id = 70927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr gestohlene Totems", progress = "Seid Ihr hier, um unsere Totems zurückzubringen?", completion = "Es gibt zu viele auf diesen Inseln, die unser Volk ausnutzen. Unsere Totems zu verlieren ist, als würden wir einen Teil von uns selbst verlieren. Unser Erbe! Ihr habt unseren Dank dafür, dass Ihr sie zurückgebracht habt, Jungspund." }
quests[70928] = { id = 70928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdtrophäe", progress = "Was habt Ihr für mich, Fremdling?", completion = "Der Klan Shikaar erkennt eine großartige Jagdtrophäe, wenn er sie sieht. Das wird Euch viel Gunst in unseren Augen einbringen." }
quests[70929] = { id = 70929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Jagdtrophäen", progress = "Was habt Ihr für mich, Fremdling?", completion = "Nur die größten Jäger können so viele großartige Jagdtrophäen vorweisen. Ihr ehrt die Jagd." }
quests[70930] = { id = 70930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teetrinken und abwarten", description = "Heute ist ein Fest des Tees: gebraut, gekühlt oder ganz anders! Es gibt auch extravagante kleine Kuchen und Kekse.\n\nAber es gibt eine seltene Zutat auf den Inseln, von der ich glaube, dass sie eine ganz neue Geschmacksdimension entfalten könnte! Tief im insektenverseuchten Reich des Schaudernetztals wächst ein Busch mit dem wunderbarsten, erhebenden Laub: der Kaltbisspfeilblattbusch.\n\nDie Drachenschuppenexpedition hat die Gegend vor Kurzem erforscht, vielleicht kann einer von ihnen Euch helfen?", sourceObjective = "Sprecht mit Lilial Dämmerbruch im Schaudernetztal.", completion = "Ein \"Kaltbisspfeilblatt\"? Hmm...", sourceObjectiveStatus = "unverified-source-field" }
quests[70931] = { id = 70931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüsternde Fragmente", description = "Ich glaube, Valthrux versucht, durch den Splitter, den wir geborgen haben, mit uns zu kommunizieren.\n\nWir können das zu unserem Vorteil nutzen, solange wir unseren Verstand vor dem Einfluss des Artefakts schützen.\n\nIch habe mich hinsichtlich der Splitterflammen geirrt. Sie haben leider schon mehrere Splitterfragmente gefunden.\n\nValthrux' Flüstern behauptet, sie sind kurz davor, den Standort zu lokalisieren.\n\nNehmt den Splitterflammen die Splitter ab, bevor sie das Artefakt finden!", sourceObjective = "Sammelt 40 flüsternde Fragmente von den Splitterflammen.", progress = "Das Flüstern... Es wird... lauter... Habt Ihr die Fragmente?", completion = "Ausgezeichnet. Mit so vielen Splittern wird es leicht werden, das Artefakt zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[70932] = { id = 70932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein würziges Leben", description = "Für viele gehört Fleisch zu einem Essen einfach dazu. Aber was gehört zu jedem Fleischgericht dazu?\n\nGewürze!\n\nEin Gewürz übertrifft alle anderen in Geschmack, Textur und Seltenheit, und es gibt es hier auf den Inseln. Leider kann es nur bei Elementaren gefunden werden, die in den Tiefen der Obsidianfeste leben. Das Gebiet wird gerade von den Djaradin kontrolliert.\n\nVielleicht könnt Ihr mehr von diesem seltsamen Troll erfahren, den ich auf dem Weg hierher getroffen habe. Ich glaube sein Name war... Gaunah.", sourceObjective = "Sprecht mit Gaunah am Obsidianthron.", completion = "Was wollt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[70934] = { id = 70934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umarmung des Salamanthers" }
quests[70935] = { id = 70935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangen und freilassen: Inselfinnenschwertfisch", progress = "Wenn wir diese Stelle überfischen, wird es für niemanden mehr Fisch geben. Nachhaltigkeit ist der Schlüssel.\n\nBringt mir alle Fische, die wieder zurück in die Gewässer sollen.", completion = "Ich werde sie wieder in die Gewässer freilassen. Fischerei ist eine verantwortungsvolle Aufgabe." }
quests[70936] = { id = 70936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Tuskarrtotems", sourceObjective = "Ihr da, Jungspund! Unsere Krieger tragen Totems bei sich, wenn sie auf den Dracheninseln reisen, weshalb unsere Feinde es lieben, diese als Trophäen zu nehmen. Das können wir so nicht stehen lassen! Bitte bringt alle Totems zurück, die Ihr findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[70937] = { id = 70937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was Valthrux einst war", description = "<To'tik flüstert.>\n\nDas gefällt mir nicht. Mysteriöse Artefakte, die großartige Versprechen flüstern? Das klingt nicht gut.\n\nAber wir können nicht einfach umkehren... ansonsten bekommen die Splitterflammen es noch in die Finger. Was auch immer \"es\" ist...\n\nIch kenne mich mit Ruinen wie diesen gut aus. Die blauen Drachen haben oft Notizen über ihre Arbeit zurückgelassen. Haltet die Augen offen, dann könnt Ihr vielleicht welche finden.\n\nWir können die Hinweise, die Ihr entdeckt, nutzen, um Alia und Kattigat zu warnen.", sourceObjective = "Findet Hinweise darauf, was das Artefakt Valthrux wirklich ist.", completion = "Mal sehen, was Ihr gefunden habt...", sourceObjectiveStatus = "unverified-source-field" }
quests[70938] = { id = 70938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinschaftliche Festmahle", description = "Da seid Ihr ja, {name}! Die Suppe steht auf dem Tisch!\n\n\n\nBeeilt Euch besser und geht nach Iskaara. Der große Kinook sucht nach Euch.\n\n\n\nEinmal hat er mir gesagt, ich soll einen schleimigen, ekligen Stachelfisch für die Suppe holen, und ich wollte nicht, als rief ich: \"Nein, Chefkoch!\"\n\n\n\nEr war so wütend, dass ich dachte, er würde mich in die Suppe werfen!", sourceObjective = "Sprecht mit dem großen Kinook bei Iskaara im Azurblauen Gebirge.", completion = "Seid Ihr bereit, etwas Magie zu wirken, Abenteurer?\n\nNein, ich meine nicht dieses Handwedelzeug, das manche so mögen. Ich meine die mystischen Aromenkünste, das tiefe Wissen um Zutaten und Geschmack, und die Art, auf die eine Suppe mit dem Koch spricht und ihn wissen lässt, was sie braucht. Läuft Euch da gerade das Wasser im Mund zusammen? Nein? Dann wohl nur bei mir.\n\nKochen wir!", sourceObjectiveStatus = "unverified-source-field" }
quests[70939] = { id = 70939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochgerät", sourceObjective = "Wollt Ihr ebenfalls ein großer Suppenmeister werden?\n\nIch kann's kaum erwarten, endlich über den Rand des großen Kessels schauen zu können! Dann bin ich endlich groß genug, um ein Festmahl anzuführen!\n\nHier, das ist für Euch! Es wird Euch auf Eurer Suppenreise helfen! Sagt Bescheid, wenn Ihr irgendwas anderes kaufen wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[70940] = { id = 70940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagen des Champions der Tuskarr", sourceObjective = "Die Taten der Tuskarr von den Dracheninseln sind viele!\n\nAber über die Jahre gingen einige unserer Geschichten verloren. Viele Reisende kehrten nie von ihren Reisen zurück, konnten ihre Geschichten nicht erzählen.\n\nBitte, wenn Ihr Schriftrollen findet, die berichten, was unsere verlorenen Stammesmitglieder erlebten, bringt sie mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[70941] = { id = 70941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angellöcher", description = "Erneut hallo! Wusstet Ihr, dass ich der besteste Fischer im Dorf werde? Ich habe mal einen riesigen Piranha gefangen. Er hat versucht, mein Gesicht zu fressen!\n\n\n\n<Rowie schaut sich gedankenverloren um.>\n\n\n\nOh, ja! Ich habe eine Nachricht für Euch. Nunvuq in Iskaara will Euch etwas über Angellöcher beibringen.", sourceObjective = "Sprecht mit Nunvuq bei Iskaara im Azurblauen Gebirge.", completion = "Grüße, Anglerfreund.\n\nIch zögere fast etwas, Euch von diesen friedlichen Angellöchern zu erzählen. Aber ich muss, denn es nicht zu tun würde Euch ein wahres Füllhorn an Fischen und außerdem die Freude und Entspannung des Angelns vorenthalten.\n\nWenn ich es allen erzähle, mache ich mir Sorgen, dass mein Angelplatz zu überlaufen wird, aber ich muss auch zugeben, dass ich nur eine gewisse Menge Ruhe und Frieden aushalte. Eine gute Unterhaltung beim Angeln mit Freunden ist noch viel entspannender, als allein zu angeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[70942] = { id = 70942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochlandfischen", sourceObjective = "Grüße, Freund! Wie ich sehe, lernt Ihr die Wege der Tuskarr, und damit auch die Wege der Fische.\n\nWenn Ihr wollt, könnte ich Euch etwas herstellen, mit dem Ihr an den Hochlandtümpeln der Dracheninseln angeln könnt. Glaubt Ihr, Ihr seid bereit für die Herausforderung?", sourceObjectiveStatus = "unverified-source-field" }
quests[70943] = { id = 70943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpunieren", sourceObjective = "Meine Güte, Ihr lernt schnell! Eure Angelkünste werden immer besser.\n\nSehen wir mal, wie Ihr mit einem Speer umgeht. Ich erschaffe für Euch Eure erste eigene Harpune der Tuskarr. Wollen wir doch mal sehen, was Ihr damit erlegt!\n\nIch bin sicher, Ihr werdet uns wie immer beeindrucken.", sourceObjectiveStatus = "unverified-source-field" }
quests[70944] = { id = 70944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisfischen", sourceObjective = "Ihr habt alle meine Erwartungen übertroffen. Und Ihr werdet immer noch besser! Ihr werdet sicher mehr übers Angeln erfahren wollen...\n\nHabt Ihr Euch je gefragt, was für leckere Happen unter dem Eis schwimmen? Eisfischen erfordert Können, aber ich glaube, Ihr seid der Herausforderung gewachsen.\n\nWenn Ihr mir die richtigen Materialien bringt, können wir anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70945] = { id = 70945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danke, sehr Netz", sourceObjective = "Eure Netze scheinen Euch an den Angellöchern gute Dienste zu leisten, aber ich glaube, das geht noch besser!\n\nWenn Ihr mir die Materialien versorgt, kann ich Euch bei der Herstellung von Verbesserungen helfen, mit denen Ihr noch mehr fangen könnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[70946] = { id = 70946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niemand darf es führen", description = "Was Ihr gefunden habt, klingt, als hätte die Macht des Artefakts alle, die sie bisher beansprucht haben, ins Verderben gestürzt.\n\nDie Drachenbrut, die hier lebte, hat sich deswegen gegenseitig umgebracht. Die Splitterflammen scheinen ebenfalls von seinem Einfluss korrumpiert zu werden.\n\nWir müssen dieses Artefakt finden. Es muss zerstört werden, bevor es noch mehr Schaden anrichten kann.\n\nWir müssen Alia und Kattigat davon überzeugen.", sourceObjective = "Überredet Alia, Valthrux zu zerstören.", progress = "Hoffen wir, dass das funktioniert...", completion = "Das ist schlimmer, als ich erwartet habe. Viel schlimmer.", sourceObjectiveStatus = "unverified-source-field" }
quests[70947] = { id = 70947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatzbesessener Trambladd" }
quests[70948] = { id = 70948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Petri Heil, Petri Dank und Petri-hinfort-mit-Euch!", sourceObjective = "Seid Ihr bereit für eine außergewöhnliche Herausforderung und zusätzliche Gefahr bei Eurem Lieblingszeitvertreib Angeln?\n\nIch kann Euch etwas herstellen, mit dem Ihr die aufregendste Art von Fisch angeln könnt: Diejenige, die in den Lavaflüssen der Dracheninseln heimisch ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[70950] = { id = 70950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch größere Fische aufspießen", sourceObjective = "Wie gefällt Euch die Harpune? Ich würde gerne die Geschichte Eures größten Fangs damit hören!\n\nAber was, wenn ich Euch sagen würde, dass wir das Harpunieren noch einfacher machen können? Ich habe einige Entwürfe, die genau das erreichen. Schaut hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[70951] = { id = 70951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es rappelt in der Angelkiste" }
quests[70952] = { id = 70952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgebene... oder versteckte Truhen", sourceObjective = "Ich verrate Euch ein kleines Geheimnis.\n\nEinige unserer weniger freundlichen Nachbarn neiden uns unsere Angelfertigkeiten... und unsere Angelplätze.\n\nSie dringen in unsere Fischgründe ein, stehlen unsere Angelkisten und verstecken sie an der Küste, damit wir sie nicht auf frischer Tat ertappen können. Ich sage Euch, wonach Ihr Ausschau halten müsst, und Ihr könnt Euch vielleicht ein paar nützliche Vorräte sichern, wenn Ihr angeln geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[70953] = { id = 70953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfbedeckung der Tuskarr", sourceObjective = "Seid gegrüßt, mein Freund.\n\nIhr wart so freundlich zu unserer Gemeinschaft hier in Iskaara. Ich habe von Euren Taten gehört und wollte Euch zum Dank etwas stricken.\n\nBitte, sucht Euch etwas aus! Ich habe viele Kopfbedeckungen gestrickt, um die langen Winterstunden zu überstehen. Wenn Ihr möchtet, kann ich Euch den Rest gern auch verkaufen, wenn Ihr wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[70954] = { id = 70954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steigende Neugier", sourceObjective = "Obwohl die Gnolle weiterhin den wichtigsten Teil meiner Forschung darstellen, bin ich doch auch neugierig auf die kürzlich zurückgekehrten Drachen.\n\nNach ausführlichen Studien und Beobachtungen habe ich begonnen, meine Notizen zu dem Thema niederzuschreiben. Sie sind noch lange nicht vollständig, aber wenn sie es sind, werden sie Euch sicher gute Dienste leisten.\n\nMöchtet Ihr bis dahin eines meiner anderen Manuskripte ansehen? Ich habe begonnen, diese für Gegenstände einzutauschen, die mir bei meinen weiteren Studien helfen, wenn Ihr also mehr wissen wollt, kommt erneut vorbei!", sourceObjectiveStatus = "unverified-source-field" }
quests[70955] = { id = 70955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faszinierende Flieger", sourceObjective = "Ich habe gestern einen Drachen mit Fleckenmuster vorbeifliegen sehen! Das war für mich mit Sicherheit das erste Mal, aber Ihr seht derlei Dinge bestimmt oft auf Euren Reisen.\n\nNatürlich habe ich dennoch genaue Notizen gemacht, für den Fall, dass es sich um eine neue Unterart handelt. Es hatte auch einige weitere, faszinierende Eigenschaften, die ich bisher noch nie gesehen habe!\n\nWenn Ihr mehr über meine Beobachtungen lesen möchtet, könnt Ihr gern ein Manuskript mit Euch nehmen. Und wenn Ihr mehr Lesestoff wollt, kann ich Euch gerne welchen verkaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70956] = { id = 70956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von azurblauen Schuppen", sourceObjective = "Mögt Ihr Poesie? Wartet. Wenn nicht, sagt es mir nicht. Hanu könnte Euch hören.\n\nAuf unseren Reisen hierher haben Hanu und ich nur wenige Bestien mit blauen Schuppen außerhalb des Azurblauen Gebirges gesehen!\n\nIch stellte einige Hypothesen zu Ursprung und Natur der blauen Schuppen auf und schrieb einige davon nieder. Und Hanu hat ein wunderbares Gedicht über die perfekte blaue Farbe geschrieben!\n\nSie ist schüchtern, was ihre Gedichte angeht, also hat sie mich gebeten, es Euch zu geben. Bitte haltet es in Ehren... so wie ich sie in Ehren halte.", sourceObjectiveStatus = "unverified-source-field" }
quests[70957] = { id = 70957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die See im Westen", description = "Gefällt Euch die grüne Landschaft um uns herum, {name}?\n\nSie erinnert mich an ein Gericht von zwei Dryadenschwestern und deren Treantfreund, das ich einmal probieren durfte. Zuckerzweig war sein Name! Er lebt in der Schattenzuflucht an der Westküste der Ebenen.\n\nEs war eine Variation aus frischen Kräutern, Gemüse und Gewürzen. Und das Herz des Gerichts war eine Lage des köstlichsten Seetangs, den Ihr je gegessen habt!\n\nWas? Ihr habt noch nie Seetang gegessen? Dann müsst Ihr einfach welchen sammeln. Und bringt doch bitte genug für alle mit!", sourceObjective = "Sprecht mit Zuckerzweig in der Schattenzuflucht auf den Ebenen von Ohn'ahra.", completion = "Benötigt Ihr Unterstützung?", sourceObjectiveStatus = "unverified-source-field" }
quests[70958] = { id = 70958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfektes Pilzpanorama", description = "In der gehobenen Küche dreht sich alles darum, die genauesten Techniken auf die erlesensten Zutaten anzuwenden. Die Gerichte der gehobenen Küche sind oft den Reichen und Betuchten vorbehalten, aber hier beim Rubinfestmahl wollen wir davon nichts wissen!\n\nSchnabuli hat mir von der perfekten Zutat für das heutige Motto erzählt. Eine so seltene und exquisite, dass sie... noch nicht existiert! Verlockend, nicht wahr?\n\nDie Bronzenen haben ein Portal in eine gefährliche Zukunft entdeckt. Eine, in der es einen schwarzen Trüffel von unvorstellbarer Köstlichkeit gibt.\n\nIhr müsst dorthin!", sourceObjective = "Sprecht mit Wächterhauptmann Sinjoirmi am Temporalen Konflux in Thaldraszus.", completion = "Oh, {name}? Mein Teller ist voll, aber für Euch ist immer ein Platz am Tisch frei.", sourceObjectiveStatus = "unverified-source-field" }
quests[70959] = { id = 70959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knuffig und knuddelig", sourceObjective = "Liebt Ihr Tiere?\n\nNatürlich tut Ihr das, wer nicht? Selbst die gruseligen sind echt toll!\n\nWollt Ihr Euch um eins der Tiere kümmern, die ich ganz allein gezähmt habt? Ich kann auch noch mehr zähmen, wenn Ihr sie kaufen wollt. Solange Ihr versprecht, Euch gut um sie zu kümmern!", sourceObjectiveStatus = "unverified-source-field" }
quests[70960] = { id = 70960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Händlerkleidung", sourceObjective = "Hallo, Abenteurer.\n\nIch rühme mich herausragender Fertigkeiten in der Lederverarbeitung. Ich würde mich geehrt fühlen, wenn Ihr diesen Umhang als Zeichen unserer Dankbarkeit für Eure Hilfe annehmen würdet.\n\nWenn Ihr eine Vorliebe für Lederrüstungen habt, wäre ich auch mehr als bereit, Euch einen Satz unserer besten Ausrüstung zum Kauf anzubieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[70961] = { id = 70961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nötige Rüstung auf sich nehmen", sourceObjective = "Seid erneut gegrüßt! Ihr habt so viel für uns getan, Freund! Ohne Eure Hilfe wären wir wirklich in Schwierigkeiten.\n\nAls Zeichen unseres Danks möchte ich Euch eins meiner graugefiederten Schulterpolster geben. Sie sollten Euch auf Euren Abenteuern Wärme spenden.\n\nWenn Ihr möchtet, dass ich Euch einen robusteren Rüstungssatz herstelle, bringt mir einfach die Materialien, um ihn herzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70962] = { id = 70962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gemütlicher Sitz", sourceObjective = "Nach einem langen Arbeitstag tut es gut, sich auszuruhen. Ich habe ein bequemes Kissen erfunden, das dabei hilft. Es ist sehr kuschelig!\n\nWollt Ihr eins haben? Ich mache Euch gerne eins, wenn Ihr mir die Materialien dafür bringt!", sourceObjectiveStatus = "unverified-source-field" }
quests[70963] = { id = 70963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halt fürs Handgelenk", sourceObjective = "Seid gegrüßt, Freund. Ich habe Euch ein paar Armschienen hergestellt, die Euch auf Euren Reisen helfen sollten.\n\nSehe ich da etwa einen Hauch von Spott, Jungspund? Lasst mich Euch darüber aufklären, wie wichtig guter Halt fürs Handgelenk ist! Ihr solltet sie alle paar Stunden dehnen und sie mit Rüstung stützen, wenn Ihr anstrengende Aktivitäten durchführt! Haltet sie nicht stundenlang in seltsamen Winkeln und...\n\n<Arvik fährt noch eine Weile so fort.>", sourceObjectiveStatus = "unverified-source-field" }
quests[70964] = { id = 70964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echt anziehend!", sourceObjective = "<Arvik untersucht Eure Armschienen und grummelt so etwas wie Zustimmung.>\n\nNa gut, habt Ihr Eure Schultern auch gestützt? Viele erkennen das nicht, aber gute Schulterstücke sind wichtig, um das Gewicht Eurer übrigen Ausrüstung zu verteilen. Ohne habt Ihr später im Leben Rückenschmerzen!\n\n<Arvik reibt sich den Rücken.>\n\nUnd außerdem schützen sie Euch gegen fallende Trümmer. Bei all den Drachen, Gnollen, Zentauren... da fliegt so viel herum oder wird geworfen. Es ist einfach nicht sicher. Hier, prüft meine Ausrüstung und passt auf Eure Schultern auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[70965] = { id = 70965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Goldener Gurt der Hüterin", description = "<Die angebrachte Notiz ist mit schöner Kalligrafie verziert.>\n\nDie Archivare bitten alle Expeditionsteilnehmer, nach dem goldenen Gurt der Hüterin für unser Artefaktarchiv zu suchen.\n\nIm Falle des Funds bitte bei Katalogisiererin Jakes zur Bearbeitung und Vergütung abgeben.\n\nIhr könnt Eure Suche an unserer nördlichen Ausgrabungsstätte beginnen, wo laut Bericht der Elementaristin Taiyang ein fehlgeleiteter Hüter Probleme verursacht.", sourceObjective = "Findet den goldenen Gurt der Hüterin.", progress = "Habt Ihr etwas für die Archive?", completion = "Puh, bin ich froh, dass ich dieses schwere Ding nicht tragen muss!\n\nIch werde sicherstellen, dass das ordentlich dokumentiert, erforscht und für die Expedition aufbewahrt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[70966] = { id = 70966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfach handeln", sourceObjective = "Seid Ihr viel gereist? Ihr seht nicht so aus: Euch fehlt einer meiner stabilen Rucksäcke!\n\nEin guter Rucksack macht in der Welt da draußen wirklich einen Unterschied. Ihr habt meinen Leuten so viel geholfen, daher will ich Euch einen meiner besten einfachen Rucksäcke anbieten.\n\nIch habe auch noch viele andere Rucksäcke! Wenn Ihr einen guten Handel anbieten wollt, wäre ich froh, mit Euch zu handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[70967] = { id = 70967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischige Unterhaltung", sourceObjective = "Angeln ist großartig. Ich liebe es! Ich esse und träume davon. Und wenn ich nicht angeln bin, stelle ich Angelausrüstung her!\n\nWenn ich eine Sache in meinen vielen Angeljahren gelernt habe, dann dass man da draußen ein wenig Spaß haben muss... mit Gewohnheiten brechen, über den Netzrand hinausblicken!\n\nHier ist etwas Ausrüstung, die ich mir ausgedacht habe, um neuen Anglern wie Euch zu helfen! Ich schenke Euch eine Hälfte, aber wenn Ihr beide haben wollt, verkaufe ich sie Euch gerne.", sourceObjectiveStatus = "unverified-source-field" }
quests[70968] = { id = 70968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teil des Stoffs, Teil der Gemeinschaft", sourceObjective = "Es ist mir eine Ehre, Euch dieses Geschenk für alles, was Ihr für uns getan habt, zu überreichen. Die Farben unserer Gemeinschaft sind in den Stoff gewoben und symbolisieren, wie wir alle zu einer Gemeinschaft verwoben sind.\n\nTragt es mit Stolz, Freund!", sourceObjectiveStatus = "unverified-source-field" }
quests[70969] = { id = 70969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teil der Gemeinschaft werden", sourceObjective = "Grüße, Freund! Geschichten Eurer Heldentaten sind im Azurblauen Gebirge weithin bekannt: von Iskaara über Imbu bis zum Weiler. Ihr habt Euch wieder und wieder bewiesen, und wir sind dankbar dafür. \n\nHäuptling Brena hat verkündet, dass Ihr Euch einen Ehrenplatz in unserer Gemeinschaft verdient habt... und in unserer Familie. Ihr werdet auf ewig als Mitglied von Iskaara bekannt sein. Habt Dank für alles, was Ihr getang habt, Freund. Nehmt bitte auch diese urzeitliche Infusion. Daraus könnt Ihr Euch einen großartigen Gegenstand herstellen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70970] = { id = 70970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Absichten", description = "Ich weiß vielleicht, wo das Artefakt ist. Alia hat fanatisch vor sich hin geflüstert, als Ihr all die Splitter zurückgebracht habt.\n\nSie sprach ständig von einer \"Höhle\" und davon, wie die Spinnen von ihr angezogen werden.\n\nIn der Gegend vor uns gibt es keine Höhle, deswegen glaube ich, dass tiefer in den Ruinen eine liegen könne.\n\nWir bleiben hier und halten den Fluchtweg offen, {name}. Bitte rettet Alia und zerstört dieses verfluchte Artefakt.", sourceObjective = "Haltet Alia Segelstrahl auf und zerstört das Artefakt Valthrux.", progress = "Hoffen wir, dass das funktioniert...", completion = "To'tik hatte recht. Dieser Ort ist verflucht.\n\nWir werden den Kirin Tor davon berichten, was hier passiert ist, {name}. Habt Dank für Eure Hilfe.\n\nDiese Lektion werde ich nicht so bald vergessen...", sourceObjectiveStatus = "unverified-source-field" }
quests[70971] = { id = 70971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen für jeden Arm", sourceObjective = "Seid Ihr für einen Übungskampf hier? Nicht? Schade.\n\nIch weiß, was Ihr für unser Volk getan habt. Es wäre mir eine Ehre, wenn Ihr eine meiner Waffen verwenden würdet. Sucht Euch aus, was immer Euch gefällt.\n\nLasst Euch Zeit. Mir ist bewusst, dass meine Sammlung riesig ist.\n\nWenn Ihr mehr von meinen Waffen möchtet, beweist Euer Können weiterhin. Bringt mir Gegenstände, die zeigen, dass Ihr Euer Kampfgeschick nicht verliert, dann kann ich Euch weitere Waffen anbieten!", sourceObjectiveStatus = "unverified-source-field" }
quests[70972] = { id = 70972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere treuen, schlaksigen Reittiere", sourceObjective = "Unsere Ottuks lassen sich nur von unseren erfolgreichsten Kriegern reiten.\n\nIch denke, es ist an der Zeit, dass wir herausfinden, ob einer von ihnen eine Bindung mit Euch eingeht. Sie sind unglaublich loyal, aber sie haben auch gern Spaß!\n\nIch überlasse es Euch und den Ottuks, welcher Euer Begleiter sein wird.\n\nOttuks, die groß genug zum Reiten sind, sind selten, und ihr Zaumzeug ist teuer. Wenn Ihr also noch einen ausbilden wollt, müssen die anderen Trainer und ich Euch im Gegenzug um einen großen Handel bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[70975] = { id = 70975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Immerbrennendes Feuerherz", description = "<Die angebrachte Notiz ist mit schöner Kalligrafie verziert.>\n\nDie Archivare bitten alle Expeditionsteilnehmer, nach dem immerbrennenden Feuerherz für unser Artefaktarchiv zu suchen.\n\nIm Falle des Funds bitte bei Katalogisiererin Jakes zur Bearbeitung und Vergütung abgeben.\n\nEinige Expeditionsmitglieder haben berichtet, dass sie im Norden einen riesigen Feuerelementar gesehen haben, der von den Primalisten kontrolliert wird. Möglicherweise bietet er eine Gelegenheit, eines zu erwerben.", sourceObjective = "Findet das immerbrennende Feuerherz.", progress = "Habt Ihr etwas für die Archive?", completion = "Die Primalisten lieben ihre Elementare einfach, nicht wahr??\n\nIch werde sicherstellen, dass das ordentlich dokumentiert, erforscht und für die Expedition aufbewahrt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[70976] = { id = 70976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwänzen und Schlittenfahren", description = "Wie Ihr vielleicht wisst, sind die Kinder von Iskaara sehr selbstständig. Sie lernen von klein auf, sich selbst zu versorgen.\n\n\n\nEs ist eine Art Mutprobe unter den älteren Kindern, sich auf den Eisberg südöstlich von hier zu schleichen. Kiopo, das älteste unserer Kinder, ist gerade dort. Sagt ihm, dass ich Euch geschickt habe, dann wird er Euch einen unserer Schlitten anbieten!\n\n\n\nAh, das erinnert mich an meine Jugend... da draußen... mit meinen Freunden...", sourceObjective = "Sucht Kiopo auf der Insel im Südosten auf.", completion = "Oh, Murik hat Euch geschickt? Er ist echt nett, also müsst Ihr auch echt nett sein!\n\nWarum hat er Euch geschickt? Ein Schlitten? Natürlich kann ich Euch einen Schlitten geben!\n\nWir haben zwei Arten. Aber wenn Ihr beide wollt, müsst Ihr mir gutes Zeug zum Tauschen bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70977] = { id = 70977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruckscaps", sourceObjective = "IHR BRINGEN SCAPS MAMPFIES? BRINGEN FISCHIE?\n\nNEIN?\n\n<SCAPS schaut Euch an, als Ihr auf seinen Rucksack zeigt.>\n\nWOLLEN RÜCKENSACK?\n\n<SCAPS überlegt.>\n\nIHR NEHMEN RÜCKENSACK, JA?\n\nABER NÄCHSTES MAL... BRINGEN FISCHIE! DANN GEBEN SACK!\n\nICH HUNGRIG!", sourceObjectiveStatus = "unverified-source-field" }
quests[70978] = { id = 70978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagen der Champions der Dracheninseln", sourceObjective = "Junger Freund! Die Dracheninseln sind voller Geschichten, die zahllose Generationen zurückreichen!\n\nWenn Ihr tief in die großen Hallen und Gewölbe dieses Landes geht, dann findet Ihr bestimmt Schriftrollen, die von diesen Geschichten berichten. Wenn Ihr sie mir bringt, bekommt Ihr im Gegenzug ein besonderes Geschenk von mir!", sourceObjectiveStatus = "unverified-source-field" }
quests[70979] = { id = 70979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmaton" }
quests[70981] = { id = 70981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vollmundige See", description = "Der Duft der See! Könnt Ihr das riechen, {name}? Riecht Ihr die Vielzahl von Mineralien und das Meersalz? Sagt schon!\n\nWas den heutigen Genüssen noch fehlt, ist eine seltene Fischart, die ich einst in der Nähe von Iskaara im Azurblauen Gebirge gekostet habe. Zwei Tuskarr haben einfach einen über einem Feuer gegrillt und das hat die eisige Tundra mit dem köstlichsten Duft erfüllt.\n\nVersucht doch, einen für uns zu finden. Ich bin sicher, unsere Gäste werden ebenso bezaubert von dem Geruch der See sein, wie ich an diesem Tag.", sourceObjective = "Sprecht mit Wayun im Walfängerwinkel im Azurblauen Gebirge.", completion = "Bitte sagt mir, dass Ihr nicht mit diesem Kerl Eisenkiefer hier seid. Wir hatten schon genug Probleme mit Gorlocs, bevor er aufgetaucht ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[70983] = { id = 70983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "O'nank Strandsieb" }
quests[70984] = { id = 70984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wogenbrecher" }
quests[70985] = { id = 70985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die einsame Späherin", description = "Ich weiß, ich weiß, es ist albern. Eine Zentaurin und eine Dryade. Wir könnten kaum unterschiedlicher sein.\n\nAber seit ich die Smaragdgärten zum ersten Mal erblickt habe, wollte ich eine Dryade besser kennenlernen. Aber es will mir einfach nicht gelingen, das Richtige zu sagen oder zu tun, damit sie an mir Interesse hätten.\n\nWie ich höre, mögen sie... Pflanzen. Und niedliche Tierbabys. Und womöglich machen sie gern Jagd auf Wilderer? Ach, ich weiß nicht, wo ich anfangen soll.\n\nKönntet Ihr vielleicht mit ihnen reden? Fragt einfach ein bisschen herum, was sie gern mögen. Vielleicht habe ich dann eine Chance.", sourceObjective = "Sprecht mit Dryaden in der Schattenzuflucht.", completion = "Blumen!!\n\n<Späherin Santuun schlägt sich mit der Hand auf die Stirn.>\n\nEs ist so offensichtlich. Ich habe mal wieder viel zu kompliziert gedacht.\n\nDanke, {name}, Ihr seid einfach der Beste!", sourceObjectiveStatus = "unverified-source-field" }
quests[70986] = { id = 70986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefreite Shikzar" }
quests[70987] = { id = 70987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärke des Herzens", description = "Was könnte besser sein als ein Essen, das Ihr auf Erkundungsreisen mitnehmen könnt?\n\nStraßenimbisse sind aus den belebten Städten dieser Welt nicht mehr wegzudenken. Aber nicht jedes Gericht lässt sich gut transportieren. Die Basis großartiger Gerichte zum Mitnehmen ist die Stärke, die unterwegs alles zusammenhält. Brot, Kartoffeln, Reis und was Euch sonst noch einfällt sind das Herz der bestecklosen Küche.\n\nIch würde meinem Pandarenkollegen gerne ein köstliches Exemplar servieren, das als Springmais bekannt ist. Schnabuli hat ihn mir gezeigt, als wir uns in der Nähe der Ruinen der Titanen an der Küste des Erwachens kennenlernten.", sourceObjective = "Sprecht mit Meliane Enorath in den Ruinen des Lebensgewölbes an der Küste des Erwachens.", completion = "Großartig, Ihr seid endlich da. Ich brauche ein Dutzend mehr Kissen, drei Wandteppiche, ein Regal für Schriftrollen, einige dieser verzauberten Besen und...\n\nMoment. Ihr seid nicht von der Expedition. Was wollt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[70988] = { id = 70988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ei muss sein", description = "\"Die ganze Welt ist ein Ei.\" So geht doch der Spruch, oder?\n\nEier! Die sind die Basis aller Pralinen und einer der besten Katalysatoren kulinarischer Kreationen! Sie sind das Fett, das Säure, Schärfe und Salzigkeit auf die höchsten Podeste stellt und ihre größten Potenziale entfaltet!\n\nAuf unseren Inseln wimmelt es nur so von mächtigen Vogelarten, aber die Brisenjäger der Ebenen legen Eier, die voller Geschmack stecken!\n\nSie nisten häufig im Osten der Ebenen, fragt also im Außenposten beim Rusza'thar-Vorstoß nach.", sourceObjective = "Sprecht mit Ilana am Rusza'thar-Vorstoß auf den Ebenen von Ohn'ahra.", completion = "Oh! Hallo!\n\nVerzeiht die Unordnung hier! Ich meine, ich habe sie nicht verursacht, ich entschuldige mich nur, dass Ihr sie sehen müsst.\n\nWas nicht heißen soll, dass Ihr nicht damit klarkommt! Ich will nur sagen, dass der aktuelle Zustand unserer Möblierung Euch unangenehm sein könnte.\n\nNicht, dass wir die Möbel so haben wollen! Wir wollen sie nicht so haben, wir hatten vor... ähm...\n\nWas sagtet Ihr, braucht Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[70989] = { id = 70989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitglied der Meute", description = "Vielleicht muss sich Eurer Bakar von Artgenossen abschauen, wie man ordentlich jagt.\n\nIhr könnt Euch einige von unseren trainierten Bakar ausleihen. Nehmt sie und holt den kreisenden Protodrachen vom Himmel.\n\nSchauen wir doch mal, wie Taivan sich in einem Rudel mit seinesgleichen verhält.", sourceObjective = "Jagt den ausgehungerten Protodrachen mit Taivan und dem Rudel Jagdbakar.", progress = "Habt Ihr den Drachen schon zur Strecke gebracht? Mein Bakar sollte für Eure Beute mehr als ausreichen.", completion = "<Jadar schüttelt den Kopf.>\n\nSehr enttäuschend. Ich fürchte, Taivan ist nicht dafür gemacht, wie ein Shikaarbakar zu jagen. Sogar mir anderen Bakar an seiner Seite konnte er nicht seinen Unwillen, den Gegner anzugreifen, überwinden.\n\nSo eine Verschwendung!", sourceObjectiveStatus = "unverified-source-field" }
quests[70990] = { id = 70990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo die Wolle ist, ist auch ein Weg", description = "Obwohl fast unsere gesamte Wolle von unseren eigenen Riesenwildschafen stammt, müssen wir doch mitunter das Land nutzen, wenn die Herde schrumpft.\n\nAuf den nahen Ebenen leben wilde Riesenwildschafe. Sie sind meist temperamentvoller als die unseres Klans. Wenn Ihr diese Klinge nehmen und ihre Wolle scheren könntet, wäre das ein großer Dienst für Aylaag.", sourceObjective = "Schert die Wolle von Klippenhufschafen.", progress = "Versucht, die Hörner zu vermeiden. Sie sind so scharf wie Messer.", completion = "Ich werde diese Wolle den Handwerkern bringen. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[70992] = { id = 70992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Verlorener Tuskarrdrachen", description = "<Die angebrachte Notiz ist mit schöner Kalligrafie verziert.>\n\nDie Archivare bitten alle Expeditionsteilnehmer, nach dem verlorenen Tuskarrdrachen für unser Artefaktarchiv zu suchen.\n\nIm Falle des Funds bitte bei Katalogisiererin Jakes zur Bearbeitung und Vergütung abgeben.\n\nEinige Expeditionsmitglieder haben berichtet, dass sie einen solchen Drachen an einem Tuskarrtransporter befestigt an der Westküste gesehen haben. Aber niemand konnte ihn erreichen, da der Transporter ihn in der Luft und damit außer Reichweite hält, wenn er in Bewegung ist.", sourceObjective = "Findet den verlorenen Tuskarrdrachen.", progress = "Habt Ihr etwas für die Archive?", completion = "Ich frage mich, was all die kleinen Schriftrollen uns hier sagen wollen? Die Archivare werden ihren Spaß damit haben.\n\nIch werde sicherstellen, dass das ordentlich dokumentiert, erforscht und für die Expedition aufbewahrt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[70994] = { id = 70994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absauglösungen", description = "Wollt Ihr die Ehre haben, der weltberühmten Chefgeologin der Drachenschuppenexpedition zu assistieren? Ja, das ist richtig. Ich bin genau die, für die Ihr mich haltet. Und ich stecke in der Klemme!\n\nIch habe diesen Fluss nach neuen Sedimentproben abgesucht, aber dann begann das Wasser, die interessantesten Schlickanteile mitzureißen!\n\nIch habe hier meine patentierte Wasserfangvorrichtung, aber es braucht dringend jemanden, der herumläuft und die Elementare in sie hineinzieht.\n\nMeint Ihr, Ihr bekommt das hin?", sourceObjective = "Saugt 8 glitzernde Ströme in der Höhle östlich der Ruinen des Lebensgewölbes auf.", completion = "Ja, sehr gut! Das ist die Zusammensetzung, nach der ich gesucht habe! Ich danke Euch! Endlich mal jemand, der mir richtig zuhören kann.\n\nTut mir einen Gefallen und erzählt niemandem im Basislager etwas davon, verstanden? Meine Dissertation ist noch in Arbeit, und ich soll eigentlich über vulkanische Sedimentquellen schreiben. Das versteht Ihr doch sicher, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[70995] = { id = 70995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Fenistraszas Schädel", description = "<Die angebrachte Notiz ist mit schöner Kalligrafie verziert.>\n\nDie Archivare bitten alle Expeditionsteilnehmer, nach Fenistraszas Schädel für unser Artefaktarchiv zu suchen.\n\nIm Falle des Funds bitte bei Katalogisiererin Jakes zur Bearbeitung und Vergütung abgeben.\n\nEinige Expeditionsmitglieder haben berichtet, dass er im Besitz eines verstoßenen Djaradin in den westlichen Bergen sein soll. Aber es konnte ihn niemand davon überzeugen, ihn herauszurücken.", sourceObjective = "Findet Fenistraszas Schädel.", progress = "Habt Ihr etwas für die Archive?", completion = "<Katalogisiererin Jakes versucht verzweifelt zu verhindern, dass das aus den Augenhöhlen des Schädels strömende Magma ihre anderen Dokumente verbrennt.>\n\nJetzt WEISS ich, dass diese Archivare diese Aufträge nur ausgeben, um mich zu ärgern!\n\nAber ich werde dennoch sicherstellen, dass das ordentlich dokumentiert, erforscht und für die Expedition aufbewahrt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[70996] = { id = 70996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tang-o am Strand", description = "Oje, das klingt, als wäre Grimmhauer in Schwierigkeiten. Ich würde sagen, ich habe genug von den Konflikten des Festlands, aber...\n\nFrostbiss und ich haben eine Vorgeschichte. Und eine Rechnung zu begleichen.\n\nAch, Schande! Ich kann die anderen hier aber nicht ohne Verteidigung lassen... Wir hatten Probleme mit einem Elementar, der am Strand für Ärger gesorgt hat. Ich bin der Einzige, der es mit ihm aufnehmen kann. Das ist ein schlüpfriger Geselle... buchstäblich\n\nIch sage Euch was: Wenn Ihr Euch für mich um den Elementar kümmert, latsche ich mal rüber zu Grimmhauers Lager.\n\nWie sieht's aus, Champ?", sourceObjective = "Besiegt den wilden Tangelementar auf der Langklaueninsel.", progress = "Wie läuft es? Habt Ihr diesen glitschigen, schleimigen Elementar schon erwischt?", completion = "Ja verdammich! Ich schätze, ich komme doch meinem alten Kumpel Grimmhauer zu Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[70997] = { id = 70997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Rubinlebensband", description = "<Die angebrachte Notiz ist hastig dahingekritzelt.>\n\nExpeditionsmitglieder haben von einem Angriff der Primalisten auf die Rubinlebensbecken berichtet, der die Zerstörung zahlloser Artefakte bedeuten kann, die unsere Drachenverbündeten dort aufbewahren.\n\nToddy und Naleidea rufen alle waffenfähigen Mitglieder auf, sich dem Kampf anzuschließen und das Rubinlebensband zu suchen, wenn Ihr könnt.\n\nEs ist ein einzigartiges, unbezahlbares Artefakt, das erhalten werden muss.\n\nWenn Ihr es gefunden habt, bringt es bitte zur sicheren Verwahrung zu Katalogisiererin Jakes, bis die Drachen es wieder abholen können.", sourceObjective = "Findet das Rubinlebensband bei den Rubinlebensbecken.", progress = "Habt Ihr etwas für die Archive?", completion = "Es heißt, das wäre von Alexstrasza persönlich hergestellt worden? Den Gezeiten sei Dank, dass Ihr es gerettet habt.\n\nIch werde sicherstellen, dass das ordentlich dokumentiert, erforscht und dann sicher aufbewahrt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[71000] = { id = 71000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barst rekrutiert", description = "Abgemacht ist abgemacht. Wenn Grimmhauer Hilfe braucht, um Frostbiss endgültig zu töten, dann bin ich dabei.\n\nDen Hass, den ich noch in mir trage, hebe ich mir für Frostbiss auf. Hat Grimmhauer Euch gesagt, was passiert ist?\n\nWir alle, die mit Grimmhauer auf die Jagd gingen, dachten, wir wären unaufhaltsam. Bis wir Frostbiss trafen.\n\nFrostbiss hat uns nicht nur besiegt. Er hat uns vor allen anderen im Unterschlupf gedemütigt.\n\nWir wurden blutig und geschlagen im Unterschlupf zurückgelassen. Frostbiss hat ein Exempel an uns statuiert.\n\nJetzt ist es an der Zeit für Rache.", sourceObjective = "Berichtet Grimmhauer, dass Ihr Barst rekrutiert habt.", completion = "Da ist Barst ja. So... anstrengend wie immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[71001] = { id = 71001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Erdgebundener urzeitlicher Kern", description = "<Die angebrachte Notiz ist mit schöner Kalligrafie verziert.>\n\nDie Archivare bitten demütig alle Expeditionsteilnehmer, nach dem erdgebundenen urzeitlichen Kern für unser Artefaktarchiv zu suchen.\n\nIm Falle des Funds bitte bei Katalogisiererin Jakes zur Bearbeitung und Vergütung abgeben.\n\nJüngste Erkenntnisse und Berichte aus der Obsidianzitadelle deuten darauf hin, dass er einst im Drachenhort von Neltharus gelagert wurde. Seine aktuelle Position ist jedoch unbekannt.", sourceObjective = "Findet den erdgebundenen urzeitlichen Kern in Neltharus.", progress = "Habt Ihr etwas für die Archive?", completion = "Ich sehe schon, dass der uns Ärger bereiten wird... Ich werde die magisch versiegelten Behälter holen, die Naleidea für solche Problemfälle verzaubert hat.\n\nKeine Sorge, ich werde sicherstellen, dass das ordentlich dokumentiert, erforscht und für die Expedition archiviert wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[71002] = { id = 71002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Zauber aller Zeiten", description = "<Dieses sacht schwebende und Arkanmagie verströmende verzauberte Buch enthält zahllose Zauber und Verzauberungen, die dem chaotischen und doch wunderschönen Verstand von Millhaus Manasturm entsprungen sind.>", sourceObjective = "Lest \"Manastürmen für Anfänger\" und entdeckt Millhaus' geheimen Zauber.", completion = "<Mithilfe Eures eigenen arkanen Wissens blättert Ihr durch Millhaus' Notizen, bis Ihr eine abgegriffene Seite findet, die mit lauter Zeichnungen von Enten gefüllt ist, von klein bis groß.\n\nIn der Mitte stehen einige Worte zu Millhaus' neuester Beschwörung mit einer interessanten Notiz darunter:\n\n\"Bester Zauber aller Zeiten\".>", sourceObjectiveStatus = "unverified-source-field" }
quests[71004] = { id = 71004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Massenbindungstotem für Ohuna", description = "<Die angebrachte Notiz ist mit schöner Kalligrafie verziert.>\n\nDie Archivare bitten demütig alle Expeditionsteilnehmer, nach dem Massenbindungstotem für Ohuna für unser Artefaktarchiv zu suchen.\n\nIm Falle des Funds bitte bei Katalogisiererin Jakes zur Bearbeitung und Vergütung abgeben.\n\nEinige Expeditionsmitglieder haben berichtet, dass sie auf der Windspielanhöhe auf den Ebenen von Ohn'ahra einen besonders fähigen Primalisten gesehen haben, der die Macht dieses Totems beherrschen soll.", sourceObjective = "Findet das Massenbindungstotem für Ohuna.", progress = "Habt Ihr etwas für die Archive?", completion = "Ich verstehe nicht ganz, was der Wirbel darum soll. Fühlt sich nicht anders an als jeder andere dreckige Stein, den ich in der Hand hatte.\n\nNa ja, ich werde sicherstellen, dass das ordentlich dokumentiert, erforscht und für die Expedition aufbewahrt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[71005] = { id = 71005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Zahnsturz", description = "<Die angebrachte Notiz ist mit schöner Kalligrafie verziert.>\n\nDie Archivare bitten demütig alle Expeditionsteilnehmer, nach dem legendären Schwert Zahnsturz für unser Artefaktarchiv zu suchen.\n\nIm Falle des Funds bitte bei Katalogisiererin Jakes zur Bearbeitung und Vergütung abgeben.\n\nBerichten zufolge wurde das Schwert vor langer Zeit zerbrochen, aber Expeditionsmitglieder sprechen davon, dass die Splitterflammen Fragmente in den Ruinen auf den Ebenen von Ohn'ahra sammelt.", sourceObjective = "Findet 100 Fragmente von Zahnsturz.", progress = "Habt Ihr etwas für die Archive?", completion = "Oooh, ich liebe Puzzles! Ich sollte die Archivare fragen, ob ich helfen darf, das wieder zusammenzusetzen!\n\nIch werde sicherstellen, dass das ordentlich dokumentiert, erforscht und für die Expedition aufbewahrt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[71007] = { id = 71007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Desorientierter Wunschschwanz", description = "<Die angebrachte Notiz ist mit schöner Kalligrafie verziert.>\n\nDie Archivare bitten demütig alle Expeditionsteilnehmer, nach dem legendären Wunschschwanz für unser Artefaktarchiv zu suchen.\n\nIm Falle des Funds bitte bei Katalogisiererin Jakes zur Bearbeitung und Vergütung abgeben.\n\nEinige Expeditionsmitglieder haben berichtet, dass sie im Azurblauen Gebirge einen bunten Fisch im Inneren eines gewaltigen Wasserelementars gesehen haben, der sich mit der Beschreibung deckt.", sourceObjective = "Findet den desorientierten Wunschschwanz.", progress = "Habt Ihr etwas für die Archive?", completion = "<Katalogisiererin Jakes beugt sich zu dem Fisch herunter und lauscht aufmerksam, während sie ihm etwas zuflüstert.>\n\nIch weiß, du kannst sprechen, kleiner Kerl. Sag etwas und gestatte mir einen Wunsch! Es ist ganz leicht!\n\n<Katalogisiererin Jakes seufzt.>\n\nEs war einen Versuch wert. Ich werde sicherstellen, dass das ordentlich dokumentiert, erforscht und für die Expedition aufbewahrt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[71008] = { id = 71008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Steinherz' steinernes Herz", description = "<Die angebrachte Notiz ist mit schöner Kalligrafie verziert.>\n\nDie Archivare bitten demütig alle Expeditionsteilnehmer, nach Steinherz' steinernem Herz für unser Artefaktarchiv zu suchen.\n\nIm Falle des Funds bitte bei Katalogisiererin Jakes zur Bearbeitung und Vergütung abgeben.\n\nEinige Expeditionsmitglieder haben berichtet, dass sie Steinherz in einer Höhle im Zentrum des Azurblauen Gebirges gesehen haben.", sourceObjective = "Findet Steinherz' steinernes Herz.", progress = "Habt Ihr etwas für die Archive?", completion = "Das war mal ein schlagendes Furbolgherz? Die Primalisten haben Ideen...\n\nIch werde sicherstellen, dass das ordentlich dokumentiert, erforscht und für die Expedition aufbewahrt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[71009] = { id = 71009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist elementar, mein lieber Drakonid", description = "Grimmhauer will sich die Zähne an Frostbiss ausbeißen, was? Ich will ihn ungern enttäuschen, aber ich habe dieses Leben hinter mir gelassen, um ein Gelehrter zu werden.\n\nIch versuche, die Geschichte aufzudecken... und selbst Geschichte zu schreiben! Aber ich hänge an diesem esoterischen Rätsel dieser uralten Ruinen fest.\n\nDas Rätsel ist Folgendes: Wenn Ihr einen Kristall in der Nähe berührt, sagt er \"Folgt dem Muster\". Aber ich habe nicht die leiseste Ahnung, was das bedeutet!\n\nIch sage Euch was: Wenn Ihr mir helfen könnt, dieses Rätsel zu lösen, werde ich Grimmhauer helfen, Frostbiss ein für alle Mal den Garaus zu machen.", sourceObjective = "Helft Varsek, das Mysterium des Uralten Aussichtspunkts zu lösen.", progress = "\"Folgt dem Muster\". Was kann das bedeuten?", completion = "Oje... Ich will nicht lügen, {name}, das ist nicht mein stolzester Moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[71010] = { id = 71010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Zeitfernrohr", description = "<Die angebrachte Notiz ist mit schöner Kalligrafie verziert.>\n\nDie Archivare bitten demütig alle Expeditionsteilnehmer, nach dem Zeitfernrohr für unser Artefaktarchiv zu suchen.\n\nIm Falle des Funds bitte bei Katalogisiererin Jakes zur Bearbeitung und Vergütung abgeben.\n\nEinige Expeditionsmitglieder haben berichtet, dass sie mitgehört haben, wie ein Zwerg in den Gasthäusern von Südthaldraszus mit seinem magischen Fernrohr angibt. Wir schlagen vor, die Suche auf diese Region zu konzentrieren.", sourceObjective = "Findet das Zeitfernrohr.", progress = "Habt Ihr etwas für die Archive?", completion = "<Katalogisiererin Jakes schüttelt den Kopf und vermeidet, durch das Fernrohr zu sehen.>\n\nNein danke. Die Gegenwart bereitet mir schon genug Kopfschmerzen. Ich kann weder Vergangenheit noch Zukunft brauchen, die sich ungebeten einmischen.\n\nIch werde sicherstellen, dass das ordentlich dokumentiert, erforscht und für die Expedition aufbewahrt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[71011] = { id = 71011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Reißende Lilie", description = "<Die angebrachte Notiz ist mit schöner Kalligrafie verziert.>\n\nDie Archivare bitten demütig alle Expeditionsteilnehmer, nach der reißenden Lilie für unser Artefaktarchiv zu suchen.\n\nIm Falle des Funds bitte bei Katalogisiererin Jakes zur Bearbeitung und Vergütung abgeben.\n\nEinige Expeditionsmitglieder haben berichtet, dass sie beim Rundblick der Gelikyr in Thaldraszus eine mächtige Primalistin gesehen haben, die eine Blume an ihrem Kragen trägt. Es ist nicht bekannt, ob es sich dabei um die legendäre reißende Lilie handelt, aber es ist ein guter Ort, um mit der Suche zu beginnen.", sourceObjective = "Findet die reißende Lilie.", progress = "Habt Ihr etwas für die Archive?", completion = "Das hat uns gerade noch gefehlt, noch eine Blume, die eine seltsame Flüssigkeit absondert...\n\n<Katalogisiererin Jakes verdreht die Augen.>\n\nIch werde sicherstellen, dass das ordentlich dokumentiert, erforscht und für die Expedition aufbewahrt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[71012] = { id = 71012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varsek rekrutiert", description = "Ich schätze, ich werde die Rätsel dieses Ortes in Zukunft problemlos lösen können.\n\nLasst uns einfach nicht mit dem alten Grimmhauer hierüber sprechen, in Ordnung?\n\nIch werde mich auf den Weg zum Unterschlupf machen. Ich glaube, ich kann es jetzt vertragen, etwas angestauten Frust an Frostbiss auszulassen.", sourceObjective = "Berichtet Grimmhauer, dass Ihr Varsek rekrutiert habt.", completion = "Da ist Varsek ja. Er hat wohl endlich dieses Rätsel gelöst, das ihn so beschäftigt hat, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[71013] = { id = 71013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Rache auf leeren Magen", description = "Da wir wieder beim Thema sind, müssen wir Stoßzahn zu Stoßzahn reden. Dieser Gnoll, Frostbiss? Mit dem Ihr geredet habt?\n\nWir haben eine Vorgeschichte mit ihm.\n\nEs könnte eine Weile dauern, es zu erklären. Geht und holt etwas Fisch, während ich es Euch erzähle, Kind. Wir brauchen Essen für alle. Sie müssen gestärkt sein für das, was kommt.", sourceObjective = "Angelt 3 gefrorene Schwanzflitzer in Grimmhauers Unterschlupf.", progress = "Hier draußen zu angeln, ist harte Arbeit. Aber darum geht es.", completion = "Jetzt wisst Ihr, was auf dem Spiel steht.\n\nZeit, aufzubrechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[71014] = { id = 71014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein entfernter Furbolgfreund", description = "Barst war einer der härtesten Furbolgs, die ich je kannte. Es sagt viel über Frostbiss aus, dass seine Meute ihn im Kampf besiegt hat.\n\nAls ich zuletzt von Barst gehört habe, war er auf dem Weg zu einer Insel vor der Küste von Iskaara. Er hat etwas von \"Ruhestand\" und lauter so Unsinn gefaselt.\n\nSagt Barst, dass es an der Zeit ist, sich wieder an die Arbeit zu machen.\n\nOh, und lasst Euch nicht von seiner Sprechweise irritieren. Er reißt Euch entzwei, wenn Ihr ihn nur komisch anseht.", sourceObjective = "Findet Barst auf der Langklaueninsel.", completion = "Schaut Euch an! Ihr seid den ganzen Weg hier rübergekommen! Wie kann ich Euch helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[71015] = { id = 71015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Muskeln, kein Gehirn", description = "Varsek ist einer der zähesten Drakoniden, die Ihr je gesehen habt. Aber auch einer der dümmsten, auch wenn er das nie zugeben würde.\n\nDie Sache mit Frostbiss hat ihn erschreckt und er hat sein Leben überdacht... oder so. Er sagte, er wäre nie dazu gekommen, die Ruinen seiner Vorfahren zu studieren. Ist davongelaufen, um ein \"Gelehrter\" zu werden.\n\nHolt Varsek zurück. Er gehört da sowieso nicht hin!", sourceObjective = "Find Varsek im Uralten Aussichtspunkt.", completion = "Es ist schön, Euch hier zu treffen. Aber wie Ihr seht, bin ich damit beschäftigt, dieses Rätsel zu lösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[71016] = { id = 71016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmhauers Schwester", description = "Zuletzt kommt meine Schwester Naluki. Sie hilft im Gasthaus in Iskaara aus.\n\nGebt ihr einfach diesen Brief.\n\nÖffnet ihn nicht.", sourceObjective = "Überbringt Grimmhauers Brief seiner Schwester Naluki in Iskaara.", completion = "Na, Ihr seid mir ja mal ein Fisch auf dem Trockenen! \n\nWas ist das? Ein Brief von Grimmhauer?", sourceObjectiveStatus = "unverified-source-field" }
quests[71017] = { id = 71017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nalukis Brief", description = "Lasst mich raten: Grimm hat Euch verboten, den Brief zu öffnen?\n\nAnscheinend habt Ihr Euch daran gehalten. Kein Wunder, dass er Euch so sehr vertraut!\n\nGebt ihm diesen Fischkopf von mir. Er weiß, was das bedeutet.", sourceObjective = "Bringt Nalukis Fischkopf zum alten Grimmhauer.", completion = "<Es ist schwer zu sagen, aber Ihr glaubt, ein schwaches Lächelns auf Grimmhauers Gesicht zu erkennen. Es verblasst schnell.>\n\nDas genügt.", sourceObjectiveStatus = "unverified-source-field" }
quests[71018] = { id = 71018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewölbe der Inkarnationen: Knackt ein paar Eier", description = "Bruthüterin Diurna ist irgendwo in dieser Festung, wo sie von ihrer Kammer aus zweifellos das Gewölbe überwacht. Wenn Ihr Teile ihres Großstabes erbeuten könnt, sollten wir ihren Bau damit direkt angreifen können.\n\nDrei sollten reichen. Vier könnten zu viel sein.", sourceObjective = "Sammelt 3 Splitter des Großstabs von Bruthüterin Diurna im Gewölbe der Inkarnationen auf normalem Schwierigkeitsgrad.", progress = "Mit der Macht, die in diesen Splittern eingeschlossen ist, können wir den Gelegebau schnell erreichen.", completion = "Damit sollten wir schneller zu Diurnas Kammer hinaufkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[71019] = { id = 71019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewölbe der Inkarnationen: Knackt ein paar Eier", description = "Bruthüterin Diurna ist irgendwo in dieser Festung, wo sie von ihrer Kammer aus zweifellos das Gewölbe überwacht. Wenn Ihr Teile ihres Großstabes erbeuten könnt, sollten wir ihren Bau damit direkt angreifen können.\n\nDrei sollten reichen. Vier könnten zu viel sein.", sourceObjective = "Sammelt 3 Splitter des Großstabs von Bruthüterin Diurna im Gewölbe der Inkarnationen auf heroischem Schwierigkeitsgrad.", progress = "Mit der Macht, die in diesen Splittern eingeschlossen ist, können wir den Gelegebau schnell erreichen.", completion = "Damit sollten wir schneller zu Diurnas Kammer hinaufkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[71020] = { id = 71020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewölbe der Inkarnationen: Knackt ein paar Eier", description = "Bruthüterin Diurna ist irgendwo in dieser Festung, wo sie von ihrer Kammer aus zweifellos das Gewölbe überwacht. Wenn Ihr Teile ihres Großstabes erbeuten könnt, sollten wir ihren Bau damit direkt angreifen können.\n\nDrei sollten reichen. Vier könnten zu viel sein.", sourceObjective = "Sammelt 3 Splitter des Großstabs von Bruthüterin Diurna im Gewölbe der Inkarnationen auf mythischem Schwierigkeitsgrad.", progress = "Mit der Macht, die in diesen Splittern eingeschlossen ist, können wir den Gelegebau schnell erreichen.", completion = "Damit sollten wir schneller zu Diurnas Kammer hinaufkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[71022] = { id = 71022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wider den Widder", description = "Die Riesenwildschafe scheinen schon mal wenig Respekt vor Taivan zu haben. Wir sollten als Nächstes probieren, ob er mit dem Widder der Herde zurechtkommt.\n\nDer Widder ist Chef aller Riesenwildschafe hier und ein ziemlich sturer Kerl. Wenn Taivan seine Dominanz über den Widder behaupten kann, wird die Herde ihm gehorchen.\n\nIhr findet ihn dort auf dem Hügel. Viel Glück, Taivan. Ich fürchte, wenn auch das nicht klappt, bleibt wenig Hoffnung, dass Taivan es noch zum Hirtenbakar schafft.", sourceObjective = "Befehlt Taivan, sich dem störrischen Widder der Herde zu stellen.", completion = "Das hätte besser laufen können. Es tut mir leid, aber ich glaube nicht, dass Taivan aus dem richtigen Holz hierfür geschnitzt ist.\n\nEr ist ein sehr netter Bakar, aber er scheint nicht wirklich klug genug zu sein, um herauszufinden, wie er die Riesenwildschafe in ihren Pferch bringt, oder aggressiv genug, um das Kommando über die Herde von ihrem Widder zu übernehmen.\n\nIch fürchte, ich muss Euch mit schlechten Neuigkeiten zu Selbekh zurückschicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[71023] = { id = 71023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesehen beim Valdrakkenabkommen", description = "Eure Taten entsprechen Eurem sagenhaften Ruf, den Ihr vor Eurer Ankunft auf den Dracheninseln erlangt habt.\n\nIch möchte Euch unterstützen, indem ich Euch mit weiteren Vorräten versorge. Sucht mich in Valdrakken auf.", sourceObjective = "Sprecht mit Unatos in Valdrakken.", completion = "Es ist meine Aufgabe, diejenigen anzuerkennen, deren Mühen dem Abkommen helfen, und ihnen wiederum durch Anerkennung zu helfen. Ich bin stolz darauf, jemanden wie Euch fördern zu können. Bitte, nehmt dies als Unterstützung in Eurem Kampf gegen die Primalisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[71024] = { id = 71024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaos und Aufruhr", description = "{name}! Habt Ihr das gehört? Da ist etwas im unteren Stockwerk passiert.\n\nEiner meiner vertrauten Ermittler, Erima, war als erstes dort. Er braucht Eure Hilfe beim Sammeln der Beweise, während er versucht, die Schaulustigen zu befragen.", sourceObjective = "Helft Erima, den Zwischenfall im unteren Stockwerk des Sitzes der Aspekte zu untersuchen.", progress = "Darf ich die Karte sehen?", completion = "Ich bin dankbar, dass Hauptmann Drine Euch geschickt hat.\n\nIhr seid einfallsreich und habt scharfe Augen.", sourceObjectiveStatus = "unverified-source-field" }
quests[71026] = { id = 71026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entgegen aller Wahrscheinlichkeit", description = "Obwohl Ihr mickrigen Sterblichen einen Waffenstillstand geschlossen habt, habe ich Gerüchte gehört, dass einige von Euch sehr nachtragen sind.\n\nWenn Ihr ein paar Freunde versammelt, kann ich Euch einen Ort zeigen, an dem Ihr der anderen Seite beweisen könnt, wer wirklich überlegen ist.\n\nUnd um es spannender zu machen, habe ich einen Preis für Euch, solltet Ihr gewinnen.", sourceObjective = "Tötet 25 Hordemitglieder der Stufe 70 auf den Dracheninseln.", completion = "Gut gemacht, {class}! Sehr, sehr gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[71027] = { id = 71027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Mara'nar der Donnernde", description = "Ich bin auf der Suche nach einem mächtigen Jäger, um eine wütende Bestie zur Strecke zu bringen!\n\nEine Donnerechse namens Mara'nar der Donnernde hat sich ihren Weg vom Donnerrückgratdickicht bis zum Urzeitlichen Tal gebahnt und stört die örtliche Tierwelt. Sie hat Wasser elektrisiert, Bäume niedergerissen und Entennester zerstört.\n\nDiese Geißel muss aufgehalten werden. Erledigt sie und bringt eine ihrer Panzerplatten zu Khanswache Jebotai als Beweis.\n\nMöge Ohn'ahra Euch leiten.", sourceObjective = "Tötet Mara'nar den Donnernden im Urzeitlichen Tal und erbeutet eine seiner Panzerplatten.", progress = "Seid gegrüßt, Reisender.", completion = "Mara'nar wurde getötet. Möge es seinen Artgenossen eine Lehre sein, in ihren Gefilden zu bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[71028] = { id = 71028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdtaktiken: Segen von Ohn'ahra", description = "Euer Ruhm unter den Maruuk wächst. Hört gut zu, dann bringe ich Euch bei, wie Ihr einen Segen von Ohn'ahra herbeiruft, um Euch und Eure Verbündeten zu schützen.", sourceObjective = "Wählt einen Segen von Ohn'ahra für die große Jagd.", completion = "Mögen Ohn'ahras Winde Euch leiten und beschützen.\n\nKehrt zurück, wenn Ihr mehr Ruhm gesammelt habt, dann werde ich Euch weiter ausbilden.", sourceObjectiveStatus = "unverified-source-field" }
quests[71029] = { id = 71029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdtaktiken: Begleiterausbildung", description = "Euer Ruhm unter den Maruuk wächst weiter. Für Eure Mühen werde ich Euch beibringen, wie Ihr Euren Jagdbegleiter im Kampf effektiver einsetzen könnt.", sourceObjective = "Wählt eine zusätzliche Begleiterfähigkeit für die große Jagd.", completion = "Eure Stärke stärkt den Klan.\n\nKehrt zurück, wenn Ihr mehr Ruhm gesammelt habt, dann werde ich Euch weiter ausbilden.", sourceObjectiveStatus = "unverified-source-field" }
quests[71030] = { id = 71030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdtaktiken: Mentorschaft der Shikaar", sourceObjective = "Euer Ruhm unter den Maruuk wächst. Sucht andere Shikaar während der großen Jagd auf, sie werden Eure Kampffertigkeit verbessern, solange Ihr auf der Jagd seid.\n\nKehrt zurück, wenn Ihr mehr Ruhm gesammelt habt, dann werde ich Euch weiter ausbilden.", sourceObjectiveStatus = "unverified-source-field" }
quests[71031] = { id = 71031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdtaktiken: Tüchtigkeitsbeweis", sourceObjective = "Wie ich sehe, ist Euer Ruhm unter den Maruuk erneut gestiegen. Lasst mich Euch zeigen, wie Ihr den Nervenkitzel des Sieges durch mehrere Feinde tragen könnt.\n\nKehrt zurück, wenn Ihr mehr Ruhm gesammelt habt, dann werde ich Euch weiter ausbilden.", sourceObjectiveStatus = "unverified-source-field" }
